166	    /// Activate a Warm skill: load triples into the knowledge graph
167	    /// and parse rules. Transitions the skill to Hot.
168	    pub fn activate(
169	        &self,
170	        skill_id: &str,
171	        knowledge_graph: &KnowledgeGraph,
172	    ) -> SkillResult<SkillActivation> {
173	        let mut skills = self.skills.write().expect("skills lock poisoned");
174	        let skill = skills
175	            .get_mut(skill_id)
176	            .ok_or_else(|| SkillError::NotFound {
177	                name: skill_id.into(),
178	            })?;
179	
180	        if skill.state != SkillState::Warm {
181	            return Err(SkillError::InvalidTransition {
182	                skill_id: skill_id.into(),
183	                from: skill.state.to_string(),
184	                to: "Hot".into(),
185	            });
186	        }
187	
188	        let skill_dir = self.skills_dir.join(skill_id);
189	        let mut triples_loaded = 0usize;
190	        let mut rules_loaded = 0usize;
191	        let mut memory_estimate = 0usize;
192	
193	        // Load triples if available.
194	        let triples_file = skill
195	            .manifest
196	            .triples_file
197	            .clone()
198	            .unwrap_or_else(|| "triples.json".into());
199	        let triples_path = skill_dir.join(&triples_file);
200	        if triples_path.exists() {
201	            let content = std::fs::read_to_string(&triples_path).map_err(|e| SkillError::Io {
202	                skill_id: skill_id.into(),
203	                source: e,
204	            })?;
205	
206	            let raw_triples: Vec<serde_json::Value> =
207	                serde_json::from_str(&content).map_err(|e| SkillError::InvalidManifest {
208	                    path: triples_path.display().to_string(),
209	                    message: format!("triples parse error: {e}"),
210	                })?;
211	
212	            for val in &raw_triples {
213	                let s = val["s"].as_u64().unwrap_or(0);
214	                let p = val["p"].as_u64().unwrap_or(0);
215	                let o = val["o"].as_u64().unwrap_or(0);
216	
217	                if let (Some(s), Some(p), Some(o)) =
218	                    (SymbolId::new(s), SymbolId::new(p), SymbolId::new(o))
219	                {
220	                    // Ignore duplicate triple errors.
221	                    let _ = knowledge_graph.insert_triple(&Triple::new(s, p, o));
222	                    triples_loaded += 1;
223	                }
224	            }
225	
226	            memory_estimate += content.len();
227	        }
228	
229	        // Load rules if available.
230	        let rules_file = skill
231	            .manifest
232	            .rules_file
233	            .clone()
234	            .unwrap_or_else(|| "rules.txt".into());
235	        let rules_path = skill_dir.join(&rules_file);
236	        let mut rule_tuples: Vec<(String, String, String)> = Vec::new();
237	        if rules_path.exists() {
238	            let content = std::fs::read_to_string(&rules_path).map_err(|e| SkillError::Io {
239	                skill_id: skill_id.into(),
240	                source: e,
241	            })?;
242	
243	            for (i, line) in content.lines().enumerate() {
244	                let line = line.trim();
245	                if line.is_empty() || line.starts_with('#') {
246	                    continue;
247	                }
248	                if let Some((lhs, rhs)) = line.split_once("=>") {
249	                    let name = format!("{}-rule-{}", skill_id, i);
250	                    rule_tuples.push((name, lhs.trim().to_string(), rhs.trim().to_string()));
251	                    rules_loaded += 1;
252	                } else {
253	                    return Err(SkillError::InvalidRule {
254	                        skill_id: skill_id.into(),
255	                        message: format!("line {}: missing '=>' separator", i + 1),
256	                    });
257	                }
258	            }
259	
260	            memory_estimate += content.len();
261	        }
262	
263	        // Check memory budget.
264	        let current = self.loaded_bytes.load(Ordering::Relaxed);
265	        if current + memory_estimate > self.max_bytes {
266	            return Err(SkillError::MemoryBudgetExceeded {
267	                required_mb: memory_estimate / (1024 * 1024) + 1,
268	                available_mb: (self.max_bytes.saturating_sub(current)) / (1024 * 1024),
269	            });
270	        }
271	
272	        // Commit.
273	        self.loaded_bytes
274	            .fetch_add(memory_estimate, Ordering::Relaxed);
275	        skill.state = SkillState::Hot;
276	        skill.triple_count = triples_loaded;
277	        skill.rule_count = rules_loaded;
278	        skill.memory_bytes = memory_estimate;
279	
280	        if !rule_tuples.is_empty() {
281	            self.rule_sources
282	                .write()
283	                .expect("rule_sources lock poisoned")
284	                .insert(skill_id.to_string(), rule_tuples);
285	        }
286	
287	        Ok(SkillActivation {
288	            skill_id: skill_id.into(),
289	            triples_loaded,
290	            rules_loaded,
291	            memory_bytes: memory_estimate,
292	        })
293	    }
294	
295	    /// Deactivate a Hot skill: mark inactive, free budget.
296	    /// Triples already in the KG persist until engine restart.
297	    pub fn deactivate(&self, skill_id: &str) -> SkillResult<()> {
298	        let mut skills = self.skills.write().expect("skills lock poisoned");
299	        let skill = skills
300	            .get_mut(skill_id)
301	            .ok_or_else(|| SkillError::NotFound {
302	                name: skill_id.into(),
303	            })?;
304	
305	        if skill.state != SkillState::Hot {
306	            return Err(SkillError::InvalidTransition {
307	                skill_id: skill_id.into(),
308	                from: skill.state.to_string(),
309	                to: "Warm (deactivate)".into(),
310	            });
311	        }
312	
313	        self.loaded_bytes
314	            .fetch_sub(skill.memory_bytes, Ordering::Relaxed);
315	        skill.state = SkillState::Warm;
316	        skill.memory_bytes = 0;
317	
318	        self.rule_sources
319	            .write()
320	            .expect("rule_sources lock poisoned")
321	            .remove(skill_id);
322	
323	        Ok(())
324	    }
325	
326	    /// Get the current state of a skill, or `None` if not discovered.
327	    pub fn skill_state(&self, skill_id: &str) -> Option<SkillState> {
328	        let skills = self.skills.read().expect("skills lock poisoned");
329	        skills.get(skill_id).map(|s| s.state)
330	    }
331	
332	    /// Build an activation summary for an already-Hot skill (idempotent reload).
333	    pub fn hot_activation(&self, skill_id: &str) -> Option<SkillActivation> {
334	        let skills = self.skills.read().expect("skills lock poisoned");
335	        let skill = skills.get(skill_id)?;
336	        if skill.state != SkillState::Hot {
337	            return None;
338	        }
339	        Some(SkillActivation {
340	            skill_id: skill_id.to_string(),
341	            triples_loaded: skill.triple_count,
342	            rules_loaded: skill.rule_count,
343	            memory_bytes: skill.memory_bytes,
344	        })
345	    }
346	
347	    /// Add extra triples to a Hot skill's count (e.g. label triples loaded externally).
348	    pub fn add_triple_count(&self, skill_id: &str, extra: usize) {
349	        let mut skills = self.skills.write().expect("skills lock poisoned");
350	        if let Some(skill) = skills.get_mut(skill_id) {
351	            skill.triple_count += extra;
352	        }
353	    }
354	
355	    /// List all known skills with their current state.
356	    pub fn list(&self) -> Vec<SkillInfo> {
357	        let skills = self.skills.read().expect("skills lock poisoned");
358	        skills
359	            .values()
360	            .map(|s| SkillInfo {
361	                id: s.manifest.id.clone(),
362	                name: s.manifest.name.clone(),
363	                version: s.manifest.version.clone(),
364	                description: s.manifest.description.clone(),
365	                state: s.state,
366	                domains: s.manifest.domains.clone(),
367	                triple_count: s.triple_count,
368	                rule_count: s.rule_count,
369	            })
370	            .collect()
371	    }
372	
373	    /// Build rewrite rules from all active (Hot) skills.
374	    pub fn active_rules(&self) -> Vec<Rewrite<AkhLang, ()>> {
375	        let rule_sources = self
376	            .rule_sources
377	            .read()
378	            .expect("rule_sources lock poisoned");
379	        let mut rules = Vec::new();
380	
381	        for (skill_id, tuples) in rule_sources.iter() {
382	            for (name, lhs, rhs) in tuples {
383	                // egg::rewrite! is a macro; we must use the lower-level API.
384	                let lhs_result: Result<Pattern<AkhLang>, _> = lhs.parse();
385	                let rhs_result: Result<Pattern<AkhLang>, _> = rhs.parse();
386	                if let (Ok(lhs_pat), Ok(rhs_pat)) = (lhs_result, rhs_result) {
387	                    match Rewrite::new(name.clone(), lhs_pat, rhs_pat) {
388	                        Ok(rule) => rules.push(rule),
389	                        Err(e) => {
390	                            tracing::warn!(
391	                                skill_id,
392	                                rule = name.as_str(),
393	                                error = %e,
394	                                "failed to compile skill rule, skipping"
395	                            );
396	                        }
397	                    }
398	                } else {
399	                    tracing::warn!(
400	                        skill_id,
401	                        rule = name.as_str(),
402	                        "failed to parse skill rule patterns, skipping"
403	                    );
404	                }
405	            }
406	        }
407	
408	        rules
409	    }
410	
411	    /// Get info for a specific skill.
412	    pub fn get_info(&self, skill_id: &str) -> SkillResult<SkillInfo> {
413	        let skills = self.skills.read().expect("skills lock poisoned");
414	        let skill = skills.get(skill_id).ok_or_else(|| SkillError::NotFound {
415	            name: skill_id.into(),
416	        })?;
417	        Ok(SkillInfo {
418	            id: skill.manifest.id.clone(),
419	            name: skill.manifest.name.clone(),
420	            version: skill.manifest.version.clone(),
421	            description: skill.manifest.description.clone(),
422	            state: skill.state,
423	            domains: skill.manifest.domains.clone(),
424	            triple_count: skill.triple_count,
425	            rule_count: skill.rule_count,
426	        })
427	    }
428	}
