    /// Skill identifier.
    pub id: String,
    /// Skill name.
    pub name: String,
    /// Version.
    pub version: String,
    /// Description.
    pub description: String,
    /// Current state.
    pub state: SkillState,
    /// Domain tags.
    pub domains: Vec<String>,
    /// Triples loaded.
