        description: skill.manifest.description.clone(),
        state: skill.state,
        domains: skill.manifest.domains.clone(),
        triple_count: skill.triple_count,
        rule_count: skill.rule_count,
        action_count: skill.actions.len(),
        plan_count: skill.plans.len(),
    })
}

