//! LLM-assisted skill authoring — Phase 30c.
//!
//! Translates natural language procedure descriptions into complete skillpack
//! files (`triples.json`, `actions.json`, `plans.json`, `rules.txt`,
//! `procedures.md`).
//!
//! The pipeline uses the Candle LLM backend (Phase 26b) via a multi-pass
//! extraction strategy so each pass uses a focused prompt rather than one
//! large inference call — important for small models like Qwen2.5-1.5B.
//!
//! # Extraction passes
//!
//! 1. **Concept pass** — extract domain entities and relationships → triples
//! 2. **Action pass** — extract steps with preconditions/effects → actions
//! 3. **Plan pass** — extract goal decomposition and ordering → plans
//! 4. **Rule pass** — extract heuristics and inference patterns → rules
//! 5. **Validation pass** — check internal consistency (all action refs in
//!    plans exist, all preconditions reference known fluents)
//!
//! When the `candle-backend` feature is not enabled this module compiles but
//! `SkillAuthor::author_from_description` returns
//! `AuthorError::BackendUnavailable`.

use std::collections::HashSet;
use std::path::PathBuf;

use miette::Diagnostic;
use serde::{Deserialize, Serialize};
use thiserror::Error;

use super::{LabelTriple, SkillAction, SkillEffects, SkillManifest, SkillPlan, SkillState};

// ─────────────────────────────────────────────────────────────────────────────
// Error
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Error, Diagnostic)]
pub enum AuthorError {
    #[error("LLM backend unavailable: {reason}")]
    #[diagnostic(
        code(akh::skill::author::backend_unavailable),
        help(
            "LLM-assisted skill authoring requires the `candle-backend` feature (Phase 26b). \
             Build with `--features candle-backend` or author the skill files by hand."
        )
    )]
    BackendUnavailable { reason: String },

    #[error("extraction pass failed ({pass}): {message}")]
    #[diagnostic(
//! Rule refinement loop — Phase 30d.
//!
//! Analyses plan execution failures involving skill procedures and suggests
//! corrections to action schemas, preconditions, plan methods, and inference
//! rules.  Suggestions are stored as *pending* KG triples so the user can
//! review and approve them before they are applied.
//!
//! # Failure analysis pipeline
//!
//! 1. Collect recent plan execution failures that involved a skill's actions.
//! 2. Extract the relevant context (expected state, actual state, failed
//!    preconditions, last rule that fired).
//! 3. Pass context to the LLM (Phase 26b) with the skill's `procedures.md` for
//!    grounding.
//! 4. Parse `RefinementSuggestion`s from the LLM response.
//! 5. Store each suggestion as a pending triple in the KG:
//!    `(suggestion_id, skill:pending_refinement, skill_id)`.
//! 6. Expose pending suggestions for user review via MCP / CLI.
//!
//! When the LLM backend is unavailable, `SkillRefiner::analyze_failure` still
//! stores a heuristic suggestion based on the failure metadata alone.

use std::collections::HashMap;

use miette::Diagnostic;
use serde::{Deserialize, Serialize};
use thiserror::Error;

use super::{LabelTriple, SkillAction, SkillEffects, SkillPlan};

// ─────────────────────────────────────────────────────────────────────────────
// Error
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Error, Diagnostic)]
pub enum RefineError {
    #[error("skill not found for refinement: {skill_id}")]
    #[diagnostic(
        code(akh::skill::refine::not_found),
        help("The skill must be Hot (activated) before refinements can be generated for it.")
    )]
    SkillNotFound { skill_id: String },

    #[error("no failure context available for skill `{skill_id}`")]
    #[diagnostic(
        code(akh::skill::refine::no_failures),
        help(
            "There are no recorded plan failures for this skill. \
             Execute the skill's plans at least once before requesting refinements."
        )
//! Skill quality metrics — Phase 30e.
//!
//! Tracks per-skill effectiveness so the agent can:
//! - Surface stale/ineffective skills to the user
//! - Suggest deactivation when a skill is unused or underperforming
//! - Prioritise refinements for the most frequently failing skills
//!
//! Metrics are kept in memory and can be persisted as KG triples with
//! `skill:quality_*` predicates.
//!
//! # Staleness detection
//!
//! A skill is considered *stale* when it hasn't been used for `stale_days`
//! days AND has a triple coverage below `min_coverage`.  Stale skills are
//! candidates for deactivation to free the memory budget.

use std::collections::HashMap;

use serde::{Deserialize, Serialize};

// ─────────────────────────────────────────────────────────────────────────────
// FailureMode
// ─────────────────────────────────────────────────────────────────────────────

/// A recurring failure pattern observed during skill execution.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FailureMode {
    /// The action that failed.
    pub action: String,
    /// Category of failure.
    pub failure_type: String,
    /// How many times this failure has been recorded.
    pub count: u32,
    /// Unix timestamp of the most recent occurrence.
    pub last_occurrence: u64,
}

// ─────────────────────────────────────────────────────────────────────────────
// SkillQuality
// ─────────────────────────────────────────────────────────────────────────────

/// Per-skill quality metrics.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SkillQuality {
    /// Skill identifier.
    pub skill_id: String,

    /// Plans completed successfully / plans attempted.
    pub success_rate: f32,
    /// Total plan executions (completed + failed).

