//! Skill manager: discover, warm, activate, and deactivate skillpacks.
//!
//! Scans a skills directory for subdirectories containing `skill.json` manifests.
//! Each skill follows the lifecycle: Cold → Warm → Hot.

use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::RwLock;

use egg::{Pattern, Rewrite};

use crate::error::{SkillError, SkillResult};
use crate::graph::index::KnowledgeGraph;
use crate::graph::Triple;
use crate::reason::AkhLang;
use crate::symbol::SymbolId;

use super::{
    LoadedSkill, SkillAction, SkillActivation, SkillInfo, SkillManifest, SkillPlan, SkillState,
};

/// Manages the lifecycle of skillpacks.
pub struct SkillManager {
    skills_dir: PathBuf,
    skills: RwLock<HashMap<String, LoadedSkill>>,
    loaded_bytes: AtomicUsize,
    max_bytes: usize,
    /// Stored rule text per skill: skill_id -> Vec<(name, lhs, rhs)>.
    #[allow(clippy::type_complexity)]
    rule_sources: RwLock<HashMap<String, Vec<(String, String, String)>>>,
}

impl std::fmt::Debug for SkillManager {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("SkillManager")
            .field("skills_dir", &self.skills_dir)
            .field("loaded_bytes", &self.loaded_bytes.load(Ordering::Relaxed))
            .field("max_bytes", &self.max_bytes)
            .finish()
    }
}

impl SkillManager {
    /// Create a new skill manager.
    ///
    /// `max_memory_mb` is the total memory budget for loaded skillpacks.
    pub fn new(skills_dir: PathBuf, max_memory_mb: usize) -> Self {
        Self {
            skills_dir,
            skills: RwLock::new(HashMap::new()),
            loaded_bytes: AtomicUsize::new(0),
            max_bytes: max_memory_mb * 1024 * 1024,
            rule_sources: RwLock::new(HashMap::new()),
        }
    }

    /// Get the skills directory path.
    pub fn skills_dir(&self) -> &std::path::Path {
        &self.skills_dir
    }

    /// Scan the skills directory for subdirectories containing `skill.json`.
    ///
    /// Registers each found skill as Cold. Returns the number of skills discovered.
    pub fn discover(&self) -> SkillResult<usize> {
        if !self.skills_dir.exists() {
            return Err(SkillError::NoSkillsDir {
                path: self.skills_dir.display().to_string(),
            });
        }

        let entries = std::fs::read_dir(&self.skills_dir).map_err(|e| SkillError::Io {
            skill_id: "<discovery>".into(),
            source: e,
        })?;

        let mut count = 0;
        let mut skills = self.skills.write().expect("skills lock poisoned");

        for entry in entries {
            let entry = entry.map_err(|e| SkillError::Io {
                skill_id: "<discovery>".into(),
                source: e,
            })?;
            let path = entry.path();
            if !path.is_dir() {
                continue;
            }

            let manifest_path = path.join("skill.json");
            if !manifest_path.exists() {
                continue;
            }

            // Use the directory name as the skill ID for discovery.
            let skill_id = path
                .file_name()
                .and_then(|n| n.to_str())
                .unwrap_or("unknown")
                .to_string();

            if !skills.contains_key(&skill_id) {
                skills.insert(
                    skill_id.clone(),
                    LoadedSkill {
                        manifest: SkillManifest {
                            id: skill_id,
                            name: String::new(),
                            version: String::new(),
                            description: String::new(),
                            domains: Vec::new(),
                            weight_size_bytes: 0,
                            triples_file: None,
                            rules_file: None,
                            cli_tools: Vec::new(),
                            wasm_tools: Vec::new(),
                            tool_config: std::collections::HashMap::new(),
                            actions_file: None,
                            plans_file: None,
                            procedures_file: None,
                        },
                        state: SkillState::Cold,
                        triple_count: 0,
                        rule_count: 0,
                        memory_bytes: 0,
                        actions: Vec::new(),
                        plans: Vec::new(),
                    },
                );
                count += 1;
            }
        }

        Ok(count)
    }

    /// Parse the manifest for a Cold skill, transitioning it to Warm.
    pub fn warm(&self, skill_id: &str) -> SkillResult<SkillManifest> {
        let mut skills = self.skills.write().expect("skills lock poisoned");
        let skill = skills
            .get_mut(skill_id)
            .ok_or_else(|| SkillError::NotFound {
                name: skill_id.into(),
            })?;

        if skill.state != SkillState::Cold {
            return Err(SkillError::InvalidTransition {
                skill_id: skill_id.into(),
                from: skill.state.to_string(),
                to: "Warm".into(),
            });
        }

        let manifest_path = self.skills_dir.join(skill_id).join("skill.json");
        let content = std::fs::read_to_string(&manifest_path).map_err(|e| SkillError::Io {
            skill_id: skill_id.into(),
            source: e,
        })?;

        let manifest: SkillManifest =
            serde_json::from_str(&content).map_err(|e| SkillError::InvalidManifest {
                path: manifest_path.display().to_string(),
                message: e.to_string(),
            })?;

        skill.manifest = manifest.clone();
        skill.state = SkillState::Warm;

        Ok(manifest)
    }

    /// Activate a Warm skill: load triples into the knowledge graph
    /// and parse rules. Transitions the skill to Hot.
    pub fn activate(
        &self,
        skill_id: &str,
        knowledge_graph: &KnowledgeGraph,
    ) -> SkillResult<SkillActivation> {
        let mut skills = self.skills.write().expect("skills lock poisoned");
        let skill = skills
            .get_mut(skill_id)
            .ok_or_else(|| SkillError::NotFound {
                name: skill_id.into(),
            })?;

        if skill.state != SkillState::Warm {
            return Err(SkillError::InvalidTransition {
                skill_id: skill_id.into(),
                from: skill.state.to_string(),
                to: "Hot".into(),
            });
        }

        let skill_dir = self.skills_dir.join(skill_id);
        let mut triples_loaded = 0usize;
        let mut rules_loaded = 0usize;
        let mut memory_estimate = 0usize;

        // Load triples if available.
        let triples_file = skill
            .manifest
            .triples_file
            .clone()
            .unwrap_or_else(|| "triples.json".into());
        let triples_path = skill_dir.join(&triples_file);
        if triples_path.exists() {
            let content = std::fs::read_to_string(&triples_path).map_err(|e| SkillError::Io {
                skill_id: skill_id.into(),
                source: e,
            })?;

            let raw_triples: Vec<serde_json::Value> =
                serde_json::from_str(&content).map_err(|e| SkillError::InvalidManifest {
                    path: triples_path.display().to_string(),
                    message: format!("triples parse error: {e}"),
                })?;

            for val in &raw_triples {
                let s = val["s"].as_u64().unwrap_or(0);
                let p = val["p"].as_u64().unwrap_or(0);
                let o = val["o"].as_u64().unwrap_or(0);

                if let (Some(s), Some(p), Some(o)) =
                    (SymbolId::new(s), SymbolId::new(p), SymbolId::new(o))
                {
                    // Ignore duplicate triple errors.
                    let _ = knowledge_graph.insert_triple(&Triple::new(s, p, o));
                    triples_loaded += 1;
                }
            }

            memory_estimate += content.len();
        }

        // Load rules if available.
        let rules_file = skill
            .manifest
            .rules_file
            .clone()
            .unwrap_or_else(|| "rules.txt".into());
        let rules_path = skill_dir.join(&rules_file);
        let mut rule_tuples: Vec<(String, String, String)> = Vec::new();
        if rules_path.exists() {
            let content = std::fs::read_to_string(&rules_path).map_err(|e| SkillError::Io {
                skill_id: skill_id.into(),
                source: e,
            })?;

            for (i, line) in content.lines().enumerate() {
                let line = line.trim();
                if line.is_empty() || line.starts_with('#') {
                    continue;
                }
                if let Some((lhs, rhs)) = line.split_once("=>") {
                    let name = format!("{}-rule-{}", skill_id, i);
                    rule_tuples.push((name, lhs.trim().to_string(), rhs.trim().to_string()));
                    rules_loaded += 1;
                } else {
                    return Err(SkillError::InvalidRule {
                        skill_id: skill_id.into(),
                        message: format!("line {}: missing '=>' separator", i + 1),
                    });
                }
            }

            memory_estimate += content.len();
        }

        // ── Phase 30: Load action schemas (actions.json) ────────────────────
        let actions_file = skill
            .manifest
            .actions_file
            .clone()
            .unwrap_or_else(|| "actions.json".into());
        let actions_path = skill_dir.join(&actions_file);
        let mut loaded_actions: Vec<SkillAction> = Vec::new();
        if actions_path.exists() {
            let content = std::fs::read_to_string(&actions_path).map_err(|e| SkillError::Io {
                skill_id: skill_id.into(),
                source: e,
            })?;
            loaded_actions =
                serde_json::from_str(&content).map_err(|e| SkillError::InvalidManifest {
                    path: actions_path.display().to_string(),
                    message: format!("actions parse error: {e}"),
                })?;
            memory_estimate += content.len();
        }

        // ── Phase 30: Load plan templates (plans.json) ───────────────────────
        let plans_file = skill
            .manifest
            .plans_file
            .clone()
            .unwrap_or_else(|| "plans.json".into());
        let plans_path = skill_dir.join(&plans_file);
        let mut loaded_plans: Vec<SkillPlan> = Vec::new();
        if plans_path.exists() {
            let content = std::fs::read_to_string(&plans_path).map_err(|e| SkillError::Io {
                skill_id: skill_id.into(),
                source: e,
            })?;
            loaded_plans =
                serde_json::from_str(&content).map_err(|e| SkillError::InvalidManifest {
                    path: plans_path.display().to_string(),
                    message: format!("plans parse error: {e}"),
                })?;
            memory_estimate += content.len();
        }

        let actions_loaded = loaded_actions.len();
        let plans_loaded = loaded_plans.len();

        // Check memory budget.
        let current = self.loaded_bytes.load(Ordering::Relaxed);
        if current + memory_estimate > self.max_bytes {
            return Err(SkillError::MemoryBudgetExceeded {
                required_mb: memory_estimate / (1024 * 1024) + 1,
                available_mb: (self.max_bytes.saturating_sub(current)) / (1024 * 1024),
            });
        }

        // Commit.
        self.loaded_bytes
            .fetch_add(memory_estimate, Ordering::Relaxed);
        skill.state = SkillState::Hot;
        skill.triple_count = triples_loaded;
        skill.rule_count = rules_loaded;
        skill.memory_bytes = memory_estimate;
        skill.actions = loaded_actions;
        skill.plans = loaded_plans;

        if !rule_tuples.is_empty() {
            self.rule_sources
                .write()
                .expect("rule_sources lock poisoned")
                .insert(skill_id.to_string(), rule_tuples);
        }

        if actions_loaded > 0 {
            tracing::debug!(skill_id, actions_loaded, "loaded procedural action schemas");
        }
        if plans_loaded > 0 {
            tracing::debug!(skill_id, plans_loaded, "loaded procedural plan templates");
        }

        Ok(SkillActivation {
            skill_id: skill_id.into(),
            triples_loaded,
            rules_loaded,
            memory_bytes: memory_estimate,
            actions_loaded,
            plans_loaded,
        })
    }

    /// Deactivate a Hot skill: mark inactive, free budget.
    /// Triples already in the KG persist until engine restart.
    pub fn deactivate(&self, skill_id: &str) -> SkillResult<()> {
        let mut skills = self.skills.write().expect("skills lock poisoned");
        let skill = skills
            .get_mut(skill_id)
            .ok_or_else(|| SkillError::NotFound {
                name: skill_id.into(),
            })?;

        if skill.state != SkillState::Hot {
            return Err(SkillError::InvalidTransition {
                skill_id: skill_id.into(),
                from: skill.state.to_string(),
                to: "Warm (deactivate)".into(),
            });
        }

        self.loaded_bytes
            .fetch_sub(skill.memory_bytes, Ordering::Relaxed);
        skill.state = SkillState::Warm;
        skill.memory_bytes = 0;
        // Clear procedural data (Phase 30).
        skill.actions.clear();
        skill.plans.clear();

        self.rule_sources
            .write()
            .expect("rule_sources lock poisoned")
            .remove(skill_id);

        Ok(())
    }

    /// Get the current state of a skill, or `None` if not discovered.
    pub fn skill_state(&self, skill_id: &str) -> Option<SkillState> {
        let skills = self.skills.read().expect("skills lock poisoned");
        skills.get(skill_id).map(|s| s.state)
    }

    /// Build an activation summary for an already-Hot skill (idempotent reload).
    pub fn hot_activation(&self, skill_id: &str) -> Option<SkillActivation> {
        let skills = self.skills.read().expect("skills lock poisoned");
        let skill = skills.get(skill_id)?;
        if skill.state != SkillState::Hot {
            return None;
        }
        Some(SkillActivation {
            skill_id: skill_id.to_string(),
            triples_loaded: skill.triple_count,
            rules_loaded: skill.rule_count,
            memory_bytes: skill.memory_bytes,
        })
    }

    /// Add extra triples to a Hot skill's count (e.g. label triples loaded externally).
    pub fn add_triple_count(&self, skill_id: &str, extra: usize) {
        let mut skills = self.skills.write().expect("skills lock poisoned");
        if let Some(skill) = skills.get_mut(skill_id) {
            skill.triple_count += extra;
        }
    }

    /// List all known skills with their current state.
    pub fn list(&self) -> Vec<SkillInfo> {
        let skills = self.skills.read().expect("skills lock poisoned");
        skills
            .values()
            .map(|s| SkillInfo {
                id: s.manifest.id.clone(),
                name: s.manifest.name.clone(),
                version: s.manifest.version.clone(),
                description: s.manifest.description.clone(),
                state: s.state,
                domains: s.manifest.domains.clone(),
                triple_count: s.triple_count,
                rule_count: s.rule_count,
                action_count: s.actions.len(),
                plan_count: s.plans.len(),
            })
            .collect()
    }

    /// Return the action schemas loaded for a Hot skill (Phase 30).
    pub fn actions(&self, skill_id: &str) -> Vec<SkillAction> {
        let skills = self.skills.read().expect("skills lock poisoned");
        skills
            .get(skill_id)
            .filter(|s| s.state == SkillState::Hot)
            .map(|s| s.actions.clone())
            .unwrap_or_default()
    }

    /// Return the plan templates loaded for a Hot skill (Phase 30).
    pub fn plans(&self, skill_id: &str) -> Vec<SkillPlan> {
        let skills = self.skills.read().expect("skills lock poisoned");
        skills
            .get(skill_id)
            .filter(|s| s.state == SkillState::Hot)
            .map(|s| s.plans.clone())
            .unwrap_or_default()
    }

    /// Return all action schemas from all Hot skills (Phase 30).
    pub fn all_active_actions(&self) -> Vec<(String, SkillAction)> {
        let skills = self.skills.read().expect("skills lock poisoned");
        skills
            .values()
            .filter(|s| s.state == SkillState::Hot)
            .flat_map(|s| {
                s.actions
                    .iter()
                    .map(|a| (s.manifest.id.clone(), a.clone()))
                    .collect::<Vec<_>>()
            })
            .collect()
    }

    /// Return all plan templates from all Hot skills (Phase 30).
    pub fn all_active_plans(&self) -> Vec<(String, SkillPlan)> {
        let skills = self.skills.read().expect("skills lock poisoned");
        skills
            .values()
            .filter(|s| s.state == SkillState::Hot)
            .flat_map(|s| {
                s.plans
                    .iter()
                    .map(|p| (s.manifest.id.clone(), p.clone()))
                    .collect::<Vec<_>>()
            })
            .collect()
    }

    /// Build rewrite rules from all active (Hot) skills.
    pub fn active_rules(&self) -> Vec<Rewrite<AkhLang, ()>> {
        let rule_sources = self
            .rule_sources
            .read()
            .expect("rule_sources lock poisoned");
        let mut rules = Vec::new();

        for (skill_id, tuples) in rule_sources.iter() {
            for (name, lhs, rhs) in tuples {
                // egg::rewrite! is a macro; we must use the lower-level API.
                let lhs_result: Result<Pattern<AkhLang>, _> = lhs.parse();
                let rhs_result: Result<Pattern<AkhLang>, _> = rhs.parse();
                if let (Ok(lhs_pat), Ok(rhs_pat)) = (lhs_result, rhs_result) {
                    match Rewrite::new(name.clone(), lhs_pat, rhs_pat) {
                        Ok(rule) => rules.push(rule),
                        Err(e) => {
                            tracing::warn!(
                                skill_id,
                                rule = name.as_str(),
                                error = %e,
                                "failed to compile skill rule, skipping"
                            );
                        }
                    }
                } else {
                    tracing::warn!(
                        skill_id,
                        rule = name.as_str(),
                        "failed to parse skill rule patterns, skipping"
                    );
                }
            }
        }

        rules
    }

    /// Get info for a specific skill.
    pub fn get_info(&self, skill_id: &str) -> SkillResult<SkillInfo> {
        let skills = self.skills.read().expect("skills lock poisoned");
        let skill = skills.get(skill_id).ok_or_else(|| SkillError::NotFound {
            name: skill_id.into(),
        })?;
        Ok(SkillInfo {
            id: skill.manifest.id.clone(),
            name: skill.manifest.name.clone(),
            version: skill.manifest.version.clone(),
            description: skill.manifest.description.clone(),
            state: skill.state,
            domains: skill.manifest.domains.clone(),
            triple_count: skill.triple_count,
            rule_count: skill.rule_count,
            action_count: skill.actions.len(),
            plan_count: skill.plans.len(),
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    /// Create a temp skills directory with a test skillpack.
    fn setup_skill_dir() -> (TempDir, PathBuf) {
        let dir = TempDir::new().unwrap();
        let skills_dir = dir.path().join("skills");
        std::fs::create_dir(&skills_dir).unwrap();

        let skill_dir = skills_dir.join("astronomy");
        std::fs::create_dir(&skill_dir).unwrap();

        // Write manifest.
        let manifest = serde_json::json!({
            "id": "astronomy",
            "name": "Astronomy Pack",
            "version": "1.0.0",
            "description": "Basic astronomical knowledge",
            "domains": ["astronomy", "science"],
            "weight_size_bytes": 0,
            "triples_file": "triples.json",
            "rules_file": "rules.txt"
        });
        std::fs::write(
            skill_dir.join("skill.json"),
            serde_json::to_string_pretty(&manifest).unwrap(),
        )
        .unwrap();

        // Write triples.
        let triples = serde_json::json!([
            {"s": 1, "p": 2, "o": 3},
            {"s": 3, "p": 2, "o": 4}
        ]);
        std::fs::write(
            skill_dir.join("triples.json"),
            serde_json::to_string(&triples).unwrap(),
        )
        .unwrap();

        // Write rules.
        std::fs::write(
            skill_dir.join("rules.txt"),
            "# Astronomy rules\n(similar ?x ?y) => (similar ?y ?x)\n",
        )
        .unwrap();

        (dir, skills_dir)
    }

    #[test]
    fn discover_skills() {
        let (_dir, skills_dir) = setup_skill_dir();
        let mgr = SkillManager::new(skills_dir, 100);
        let count = mgr.discover().unwrap();
        assert_eq!(count, 1);

        let list = mgr.list();
        assert_eq!(list.len(), 1);
        assert_eq!(list[0].id, "astronomy");
        assert_eq!(list[0].state, SkillState::Cold);
    }

    #[test]
    fn warm_parses_manifest() {
        let (_dir, skills_dir) = setup_skill_dir();
        let mgr = SkillManager::new(skills_dir, 100);
        mgr.discover().unwrap();

        let manifest = mgr.warm("astronomy").unwrap();
        assert_eq!(manifest.name, "Astronomy Pack");
        assert_eq!(manifest.version, "1.0.0");
        assert_eq!(manifest.domains, vec!["astronomy", "science"]);
    }

    #[test]
    fn activate_loads_triples() {
        let (_dir, skills_dir) = setup_skill_dir();
        let mgr = SkillManager::new(skills_dir, 100);
        let kg = KnowledgeGraph::new();

        mgr.discover().unwrap();
        mgr.warm("astronomy").unwrap();
        let activation = mgr.activate("astronomy", &kg).unwrap();

        assert_eq!(activation.triples_loaded, 2);
        assert_eq!(activation.actions_loaded, 0);
        assert_eq!(activation.plans_loaded, 0);
        assert!(kg.triple_count() >= 2);
    }

    #[test]
    fn activate_loads_rules() {
        let (_dir, skills_dir) = setup_skill_dir();
        let mgr = SkillManager::new(skills_dir, 100);
        let kg = KnowledgeGraph::new();

        mgr.discover().unwrap();
        mgr.warm("astronomy").unwrap();
        let activation = mgr.activate("astronomy", &kg).unwrap();
        assert_eq!(activation.rules_loaded, 1);

        let rules = mgr.active_rules();
        assert_eq!(rules.len(), 1);
    }

    #[test]
    fn activate_loads_actions_and_plans() {
        let (dir, skills_dir) = setup_skill_dir();
        let skill_dir = dir.path().join("skills").join("astronomy");

        // Write actions.json
        let actions = serde_json::json!([
            {
                "action": "observe_star",
                "description": "Observe a star to determine its properties",
                "preconditions": ["telescope_available"],
                "effects": {
                    "initiates": ["star_observed"],
                    "terminates": ["star_unknown"]
                },
                "estimated_duration": "medium"
            }
        ]);
        std::fs::write(
            skill_dir.join("actions.json"),
            serde_json::to_string_pretty(&actions).unwrap(),
        )
        .unwrap();

        // Write plans.json
        let plans = serde_json::json!([
            {
                "goal": "classify_star",
                "method": {"type": "sequential"},
                "steps": ["observe_star"],
                "preconditions": ["has_star_to_classify"]
            }
        ]);
        std::fs::write(
            skill_dir.join("plans.json"),
            serde_json::to_string_pretty(&plans).unwrap(),
        )
        .unwrap();

        let mgr = SkillManager::new(skills_dir, 100);
        let kg = KnowledgeGraph::new();

        mgr.discover().unwrap();
        mgr.warm("astronomy").unwrap();
        let activation = mgr.activate("astronomy", &kg).unwrap();

        assert_eq!(activation.actions_loaded, 1);
        assert_eq!(activation.plans_loaded, 1);

        let actions = mgr.actions("astronomy");
        assert_eq!(actions.len(), 1);
        assert_eq!(actions[0].action, "observe_star");

        let plans = mgr.plans("astronomy");
        assert_eq!(plans.len(), 1);
        assert_eq!(plans[0].goal, "classify_star");

        let all_actions = mgr.all_active_actions();
        assert_eq!(all_actions.len(), 1);
        assert_eq!(all_actions[0].0, "astronomy");
    }

    #[test]
    fn deactivate_clears_procedural_data() {
        let (dir, skills_dir) = setup_skill_dir();
        let skill_dir = dir.path().join("skills").join("astronomy");

        let actions = serde_json::json!([{
            "action": "observe_star",
            "description": "Observe a star",
            "preconditions": [],
            "effects": {"initiates": [], "terminates": []},
            "estimated_duration": "fast"
        }]);
        std::fs::write(
            skill_dir.join("actions.json"),
            serde_json::to_string(&actions).unwrap(),
        )
        .unwrap();

        let mgr = SkillManager::new(skills_dir, 100);
        let kg = KnowledgeGraph::new();
        mgr.discover().unwrap();
        mgr.warm("astronomy").unwrap();
        let activation = mgr.activate("astronomy", &kg).unwrap();
        assert_eq!(activation.actions_loaded, 1);

        mgr.deactivate("astronomy").unwrap();

        let actions = mgr.actions("astronomy");
        assert!(actions.is_empty(), "actions cleared after deactivate");
        let all = mgr.all_active_actions();
        assert!(all.is_empty());
    }

    #[test]
    fn budget_enforcement() {
        let (_dir, skills_dir) = setup_skill_dir();
        // Extremely small budget: 0 MB.
        let mgr = SkillManager::new(skills_dir, 0);
        let kg = KnowledgeGraph::new();

        mgr.discover().unwrap();
        mgr.warm("astronomy").unwrap();
        let result = mgr.activate("astronomy", &kg);
        assert!(matches!(
            result,
            Err(SkillError::MemoryBudgetExceeded { .. })
        ));
    }

    #[test]
    fn deactivate_frees_budget() {
        let (_dir, skills_dir) = setup_skill_dir();
        let mgr = SkillManager::new(skills_dir, 100);
        let kg = KnowledgeGraph::new();

        mgr.discover().unwrap();
        mgr.warm("astronomy").unwrap();
        let activation = mgr.activate("astronomy", &kg).unwrap();
        assert!(activation.memory_bytes > 0);

        mgr.deactivate("astronomy").unwrap();

        let info = mgr.get_info("astronomy").unwrap();
        assert_eq!(info.state, SkillState::Warm);

        // Rules should be cleared.
        let rules = mgr.active_rules();
        assert!(rules.is_empty());
    }
}

//! Skill quality metrics — Phase 30e.
//!
//! Tracks per-skill effectiveness so the agent can:
//! - Surface stale/ineffective skills to the user
//! - Suggest deactivation when a skill is unused or underperforming
//! - Prioritise refinements for the most frequently failing skills
//!
//! Metrics are kept in memory and can be persisted as KG triples with
//! `skill:quality_*` predicates.
//!
//! # Staleness detection
//!
//! A skill is considered *stale* when it hasn't been used for `stale_days`
//! days AND has a triple coverage below `min_coverage`.  Stale skills are
//! candidates for deactivation to free the memory budget.

use std::collections::HashMap;

use serde::{Deserialize, Serialize};

// ─────────────────────────────────────────────────────────────────────────────
// FailureMode
// ─────────────────────────────────────────────────────────────────────────────

/// A recurring failure pattern observed during skill execution.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FailureMode {
    /// The action that failed.
    pub action: String,
    /// Category of failure.
    pub failure_type: String,
    /// How many times this failure has been recorded.
    pub count: u32,
    /// Unix timestamp of the most recent occurrence.
    pub last_occurrence: u64,
}

// ─────────────────────────────────────────────────────────────────────────────
// SkillQuality
// ─────────────────────────────────────────────────────────────────────────────

/// Per-skill quality metrics.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SkillQuality {
    /// Skill identifier.
    pub skill_id: String,

    /// Plans completed successfully / plans attempted.
    pub success_rate: f32,
    /// Total plan executions (completed + failed).
    pub total_executions: u32,
    /// Plans that completed successfully.
    pub successful_executions: u32,

    /// Recurring failure patterns.
    pub failure_modes: Vec<FailureMode>,

    /// Per-rule hit rates: rule name → fraction of inferences it participated in.
    pub rule_hit_rates: HashMap<String, f32>,
    /// Total inference passes across all rules.
    pub total_inference_passes: u64,

    /// Fraction of the skill's triples that have been queried at least once.
    pub triple_coverage: f32,
    /// Number of distinct triples queried.
    pub triples_queried: usize,
    /// Total triples the skill declared.
    pub triples_total: usize,

    /// Unix timestamp of the last successful execution (None if never used).
    pub last_used: Option<u64>,

    /// How many refinement suggestions are currently pending.
    pub refinements_pending: u32,
    /// How many refinements have been applied to this skill.
    pub refinements_applied: u32,
}

impl SkillQuality {
    /// Create a fresh quality record for a skill.
    pub fn new(skill_id: impl Into<String>, triples_total: usize) -> Self {
        Self {
            skill_id: skill_id.into(),
            success_rate: 0.0,
            total_executions: 0,
            successful_executions: 0,
            failure_modes: Vec::new(),
            rule_hit_rates: HashMap::new(),
            total_inference_passes: 0,
            triple_coverage: 0.0,
            triples_queried: 0,
            triples_total,
            last_used: None,
            refinements_pending: 0,
            refinements_applied: 0,
        }
    }

    // ─── Mutation helpers ────────────────────────────────────────────────────

    /// Record a successful plan execution.
    pub fn record_success(&mut self) {
        self.total_executions += 1;
        self.successful_executions += 1;
        self.recompute_success_rate();
        let now = now_secs();
        self.last_used = Some(now);
    }

    /// Record a failed plan execution.
    pub fn record_failure(&mut self, action: &str, failure_type: &str) {
        self.total_executions += 1;
        self.recompute_success_rate();

        let now = now_secs();
        if let Some(mode) = self
            .failure_modes
            .iter_mut()
            .find(|m| m.action == action && m.failure_type == failure_type)
        {
            mode.count += 1;
            mode.last_occurrence = now;
        } else {
            self.failure_modes.push(FailureMode {
                action: action.to_string(),
                failure_type: failure_type.to_string(),
                count: 1,
                last_occurrence: now,
            });
        }
    }

    /// Record that a specific inference rule fired during reasoning.
    pub fn record_rule_hit(&mut self, rule_name: &str) {
        self.total_inference_passes += 1;
        let hits = self
            .rule_hit_rates
            .entry(rule_name.to_string())
            .or_insert(0.0);
        // Running average: new_rate = (old_rate * (n-1) + 1) / n
        let n = self.total_inference_passes as f32;
        *hits = (*hits * (n - 1.0) + 1.0) / n;
    }

    /// Record that a rule pass occurred but this rule did NOT fire.
    pub fn record_rule_miss(&mut self, rule_name: &str) {
        self.total_inference_passes += 1;
        let hits = self
            .rule_hit_rates
            .entry(rule_name.to_string())
            .or_insert(0.0);
        let n = self.total_inference_passes as f32;
        // Rule did not fire: hit contribution is 0.
        *hits = *hits * (n - 1.0) / n;
    }

    /// Record that a triple was queried, updating coverage.
    pub fn record_triple_query(&mut self, is_new_triple: bool) {
        if is_new_triple {
            self.triples_queried += 1;
        }
        self.recompute_coverage();
    }

    /// Update the pending refinements count.
    pub fn set_refinements_pending(&mut self, count: u32) {
        self.refinements_pending = count;
    }

    /// Record that a refinement was applied.
    pub fn record_refinement_applied(&mut self) {
        self.refinements_applied += 1;
        if self.refinements_pending > 0 {
            self.refinements_pending -= 1;
        }
    }

    // ─── Derived properties ──────────────────────────────────────────────────

    /// Return the most common failure mode, if any.
    pub fn top_failure_mode(&self) -> Option<&FailureMode> {
        self.failure_modes.iter().max_by_key(|m| m.count)
    }

    /// Return rules whose hit rate is below `threshold` (likely dead rules).
    pub fn low_hit_rate_rules(&self, threshold: f32) -> Vec<(&str, f32)> {
        self.rule_hit_rates
            .iter()
            .filter(|(_, &rate)| rate < threshold)
            .map(|(name, &rate)| (name.as_str(), rate))
            .collect()
    }

    // ─── Internal ────────────────────────────────────────────────────────────

    fn recompute_success_rate(&mut self) {
        if self.total_executions == 0 {
            self.success_rate = 0.0;
        } else {
            self.success_rate = self.successful_executions as f32 / self.total_executions as f32;
        }
    }

    fn recompute_coverage(&mut self) {
        if self.triples_total == 0 {
            self.triple_coverage = 1.0; // vacuously full coverage
        } else {
            self.triple_coverage =
                self.triples_queried.min(self.triples_total) as f32 / self.triples_total as f32;
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// StalenessConfig
// ─────────────────────────────────────────────────────────────────────────────

/// Configuration for staleness detection.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct StalenessConfig {
    /// Number of days without use before a skill is considered stale.
    pub stale_days: u32,
    /// Minimum triple coverage below which a skill is considered under-utilised.
    pub min_coverage: f32,
    /// Minimum success rate below which a skill is flagged for review.
    pub min_success_rate: f32,
}

impl Default for StalenessConfig {
    fn default() -> Self {
        Self {
            stale_days: 30,
            min_coverage: 0.1,
            min_success_rate: 0.5,
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// QualityRegistry
// ─────────────────────────────────────────────────────────────────────────────

/// Registry of quality metrics for all known skills.
#[derive(Debug, Default)]
pub struct QualityRegistry {
    records: HashMap<String, SkillQuality>,
    config: StalenessConfig,
}

impl QualityRegistry {
    /// Create an empty registry with default staleness config.
    pub fn new() -> Self {
        Self::default()
    }

    /// Create a registry with custom staleness config.
    pub fn with_config(config: StalenessConfig) -> Self {
        Self {
            records: HashMap::new(),
            config,
        }
    }

    /// Ensure a quality record exists for `skill_id`.
    pub fn ensure(&mut self, skill_id: &str, triples_total: usize) {
        self.records
            .entry(skill_id.to_string())
            .or_insert_with(|| SkillQuality::new(skill_id, triples_total));
    }

    /// Get an immutable reference to a skill's quality record.
    pub fn get(&self, skill_id: &str) -> Option<&SkillQuality> {
        self.records.get(skill_id)
    }

    /// Get a mutable reference to a skill's quality record.
    pub fn get_mut(&mut self, skill_id: &str) -> Option<&mut SkillQuality> {
        self.records.get_mut(skill_id)
    }

    /// Return skill IDs that are stale under the current config.
    pub fn stale_skills(&self) -> Vec<&str> {
        let threshold_secs = self.config.stale_days as u64 * 86_400;
        let now = now_secs();

        self.records
            .values()
            .filter(|q| {
                let stale_by_time = match q.last_used {
                    None => true, // never used
                    Some(last) => now.saturating_sub(last) > threshold_secs,
                };
                let low_coverage = q.triple_coverage < self.config.min_coverage;
                stale_by_time && low_coverage
            })
            .map(|q| q.skill_id.as_str())
            .collect()
    }

    /// Return skill IDs with success rate below the configured threshold.
    pub fn underperforming_skills(&self) -> Vec<&str> {
        self.records
            .values()
            .filter(|q| q.total_executions > 0 && q.success_rate < self.config.min_success_rate)
            .map(|q| q.skill_id.as_str())
            .collect()
    }

    /// Return all quality records.
    pub fn all(&self) -> Vec<&SkillQuality> {
        self.records.values().collect()
    }

    /// Remove a skill's quality record (e.g. on full uninstall).
    pub fn remove(&mut self, skill_id: &str) {
        self.records.remove(skill_id);
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────────────────────────────────────

fn now_secs() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

// ─────────────────────────────────────────────────────────────────────────────
// Tests
// ─────────────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn success_rate_tracking() {
        let mut q = SkillQuality::new("my-skill", 10);
        q.record_success();
        q.record_success();
        q.record_failure("act_a", "precondition_unmet");
        assert_eq!(q.total_executions, 3);
        assert!((q.success_rate - 2.0 / 3.0).abs() < 1e-6);
    }

    #[test]
    fn failure_mode_dedup() {
        let mut q = SkillQuality::new("s", 5);
        q.record_failure("act_a", "timeout");
        q.record_failure("act_a", "timeout");
        q.record_failure("act_b", "precondition_unmet");
        assert_eq!(q.failure_modes.len(), 2);
        let top = q.top_failure_mode().unwrap();
        assert_eq!(top.action, "act_a");
        assert_eq!(top.count, 2);
    }

    #[test]
    fn triple_coverage() {
        let mut q = SkillQuality::new("s", 4);
        q.record_triple_query(true);
        q.record_triple_query(true);
        assert!((q.triple_coverage - 0.5).abs() < 1e-6);
        // Querying same triple again (not new) doesn't change coverage.
        q.record_triple_query(false);
        assert!((q.triple_coverage - 0.5).abs() < 1e-6);
    }

    #[test]
    fn rule_hit_rates() {
        let mut q = SkillQuality::new("s", 0);
        q.record_rule_hit("rule-0");
        q.record_rule_hit("rule-0");
        q.record_rule_miss("rule-1");
        // rule-0 hit 2 out of 3 passes
        let rate = q.rule_hit_rates["rule-0"];
        assert!(rate > 0.0 && rate <= 1.0, "rate={rate}");
    }

    #[test]
    fn staleness_detection() {
        let mut reg = QualityRegistry::with_config(StalenessConfig {
            stale_days: 1,
            min_coverage: 0.5,
            min_success_rate: 0.5,
        });
        reg.ensure("never-used", 100);
        // A skill never used has coverage 0 < 0.5, so stale.
        let stale = reg.stale_skills();
        assert!(stale.contains(&"never-used"));
    }

    #[test]
    fn underperforming_skills() {
        let mut reg = QualityRegistry::new();
        reg.ensure("bad-skill", 5);
        let q = reg.get_mut("bad-skill").unwrap();
        q.record_failure("act", "timeout");
        q.record_failure("act", "timeout");

        let under = reg.underperforming_skills();
        assert!(under.contains(&"bad-skill"));
    }

    #[test]
    fn refinement_tracking() {
        let mut q = SkillQuality::new("s", 0);
        q.set_refinements_pending(3);
        q.record_refinement_applied();
        assert_eq!(q.refinements_pending, 2);
        assert_eq!(q.refinements_applied, 1);
    }
}

