293	    /// Generate a complete skill from a natural language description.
294	    ///
295	    /// When the LLM backend is unavailable this returns a minimal stub skill
296	    /// with only the metadata populated so the caller can still save it and
297	    /// fill in the procedural files by hand.
298	    pub fn author_from_description(
299	        &self,
300	        id: &str,
301	        name: &str,
302	        description: &str,
303	        hints: ExtractionHints,
304	    ) -> AuthorResult<AuthoredSkill> {
305	        if !self.llm_available {
306	            // Return a stub — the caller can fill in files manually.
307	            return Ok(self.stub_skill(id, name, description, hints));
308	        }
309	
310	        // Full multi-pass pipeline (requires Phase 26b Candle backend).
311	        // Implemented here once the backend is wired; for now we fall back to
312	        // the stub path since we cannot call the LLM.
313	        //
314	        // Planned passes:
315	        // 1. concept_pass(description) → Vec<LabelTriple>
316	        // 2. action_pass(description, &triples) → Vec<SkillAction>
317	        // 3. plan_pass(description, &actions) → Vec<SkillPlan>
318	        // 4. rule_pass(description, &triples, &actions) → Vec<String>
319	        // 5. validate(&authored_skill)
320	        //
321	        // Each pass sends a focused prompt to the LLM and parses the JSON
322	        // response with brace-depth tracking to handle streaming tokens.
323	        tracing::warn!(
324	            skill_id = id,
325	            "LLM-assisted authoring is not yet fully wired to Phase 26b Candle backend; \
326	             returning stub skill"
327	        );
328	        Ok(self.stub_skill(id, name, description, hints))
329	    }
