782	        mgr.deactivate("astronomy").unwrap();
783	
784	        let info = mgr.get_info("astronomy").unwrap();
785	        assert_eq!(info.state, SkillState::Warm);
786	
787	        // Rules should be cleared.
788	        let rules = mgr.active_rules();
789	        assert!(rules.is_empty());
790	    }
