1	//! LLM-assisted skill authoring — Phase 30c.
2	//!
3	//! Translates natural language procedure descriptions into complete skillpack
4	//! files (`triples.json`, `actions.json`, `plans.json`, `rules.txt`,
5	//! `procedures.md`).
6	//!
7	//! The pipeline uses the Candle LLM backend (Phase 26b) via a multi-pass
8	//! extraction strategy so each pass uses a focused prompt rather than one
9	//! large inference call — important for small models like Qwen2.5-1.5B.
10	//!
11	//! # Extraction passes
12	//!
13	//! 1. **Concept pass** — extract domain entities and relationships → triples
14	//! 2. **Action pass** — extract steps with preconditions/effects → actions
15	//! 3. **Plan pass** — extract goal decomposition and ordering → plans
16	//! 4. **Rule pass** — extract heuristics and inference patterns → rules
17	//! 5. **Validation pass** — check internal consistency (all action refs in
18	//!    plans exist, all preconditions reference known fluents)
19	//!
20	//! When the `candle-backend` feature is not enabled this module compiles but
21	//! `SkillAuthor::author_from_description` returns
22	//! `AuthorError::BackendUnavailable`.
23	
24	use std::collections::HashSet;
25	use std::path::PathBuf;
26	
27	use miette::Diagnostic;
28	use serde::{Deserialize, Serialize};
29	use thiserror::Error;
30	
31	use super::{LabelTriple, SkillAction, SkillEffects, SkillManifest, SkillPlan};
32	
33	// ─────────────────────────────────────────────────────────────────────────────
34	// Error
35	// ─────────────────────────────────────────────────────────────────────────────
36	
37	#[derive(Debug, Error, Diagnostic)]
38	pub enum AuthorError {
39	    #[error("LLM backend unavailable: {reason}")]
40	    #[diagnostic(
41	        code(akh::skill::author::backend_unavailable),
42	        help(
43	            "LLM-assisted skill authoring requires the `candle-backend` feature (Phase 26b). \
44	             Build with `--features candle-backend` or author the skill files by hand."
45	        )
46	    )]
47	    BackendUnavailable { reason: String },
48	
49	    #[error("extraction pass failed ({pass}): {message}")]
50	    #[diagnostic(
51	        code(akh::skill::author::extraction_failed),
52	        help(
53	            "The LLM could not extract structured data from the provided description. \
54	             Try rephrasing with clearer step descriptions and explicit preconditions."
55	        )
56	    )]
57	    ExtractionFailed { pass: String, message: String },
58	
59	    #[error("validation failed: {message}")]
60	    #[diagnostic(
61	        code(akh::skill::author::validation_failed),
62	        help(
63	            "The generated skill failed internal consistency checks. \
64	             Review the generated files and fix the listed issues."
65	        )
66	    )]
67	    ValidationFailed { message: String },
68	
69	    #[error("I/O error writing skill to {path}: {source}")]
70	    #[diagnostic(
71	        code(akh::skill::author::io),
72	        help("Ensure the target skills directory exists and is writable.")
73	    )]
74	    Io {
75	        path: String,
76	        #[source]
77	        source: std::io::Error,
78	    },
79	
80	    #[error("serialization error: {message}")]
81	    #[diagnostic(
82	        code(akh::skill::author::serialize),
83	        help("Internal JSON serialization failure; this is a bug.")
84	    )]
85	    Serialize { message: String },
86	}
87	
88	pub type AuthorResult<T> = std::result::Result<T, AuthorError>;
89	
90	// ─────────────────────────────────────────────────────────────────────────────
91	// AuthoredSkill
92	// ─────────────────────────────────────────────────────────────────────────────
93	
94	/// A complete skill produced by the authoring pipeline.
95	#[derive(Debug, Clone, Serialize, Deserialize)]
96	pub struct AuthoredSkill {
97	    /// The skill manifest.
98	    pub manifest: SkillManifest,
99	    /// Label-based triples (concept pass).
100	    pub triples: Vec<LabelTriple>,
101	    /// Action schemas (action pass).
102	    pub actions: Vec<SkillAction>,
103	    /// Plan templates (plan pass).
104	    pub plans: Vec<SkillPlan>,
105	    /// Egg rewrite rules — one rule per line in `lhs => rhs` format.
106	    pub rules: Vec<String>,
107	    /// Original natural language text (preserved as `procedures.md`).
108	    pub source_text: String,
109	}
110	
111	impl AuthoredSkill {
112	    /// Write all skill files into `target_dir/<skill_id>/`.
113	    ///
114	    /// Creates the directory if it does not exist.  Returns the path to the
115	    /// created skill directory.
116	    pub fn write_to_disk(&self, skills_dir: &std::path::Path) -> AuthorResult<PathBuf> {
117	        let skill_dir = skills_dir.join(&self.manifest.id);
118	        std::fs::create_dir_all(&skill_dir).map_err(|e| AuthorError::Io {
119	            path: skill_dir.display().to_string(),
120	            source: e,
121	        })?;
122	
123	        // skill.json
124	        let manifest_json =
125	            serde_json::to_string_pretty(&self.manifest).map_err(|e| AuthorError::Serialize {
126	                message: e.to_string(),
127	            })?;
128	        std::fs::write(skill_dir.join("skill.json"), manifest_json).map_err(|e| {
129	            AuthorError::Io {
130	                path: skill_dir.join("skill.json").display().to_string(),
131	                source: e,
132	            }
133	        })?;
134	
135	        // triples.json
136	        if !self.triples.is_empty() {
137	            let triples_json = serde_json::to_string_pretty(&self.triples).map_err(|e| {
138	                AuthorError::Serialize {
139	                    message: e.to_string(),
140	                }
141	            })?;
142	            std::fs::write(skill_dir.join("triples.json"), triples_json).map_err(|e| {
143	                AuthorError::Io {
144	                    path: skill_dir.join("triples.json").display().to_string(),
145	                    source: e,
146	                }
147	            })?;
148	        }
149	
150	        // actions.json
151	        if !self.actions.is_empty() {
152	            let actions_json = serde_json::to_string_pretty(&self.actions).map_err(|e| {
153	                AuthorError::Serialize {
154	                    message: e.to_string(),
155	                }
156	            })?;
157	            std::fs::write(skill_dir.join("actions.json"), actions_json).map_err(|e| {
158	                AuthorError::Io {
159	                    path: skill_dir.join("actions.json").display().to_string(),
160	                    source: e,
161	                }
162	            })?;
163	        }
164	
165	        // plans.json
166	        if !self.plans.is_empty() {
167	            let plans_json =
168	                serde_json::to_string_pretty(&self.plans).map_err(|e| AuthorError::Serialize {
169	                    message: e.to_string(),
170	                })?;
171	            std::fs::write(skill_dir.join("plans.json"), plans_json).map_err(|e| {
172	                AuthorError::Io {
173	                    path: skill_dir.join("plans.json").display().to_string(),
174	                    source: e,
175	                }
176	            })?;
177	        }
178	
179	        // rules.txt
180	        if !self.rules.is_empty() {
181	            let rules_text = self.rules.join("\n");
182	            std::fs::write(skill_dir.join("rules.txt"), rules_text).map_err(|e| {
183	                AuthorError::Io {
184	                    path: skill_dir.join("rules.txt").display().to_string(),
185	                    source: e,
186	                }
187	            })?;
188	        }
189	
190	        // procedures.md — natural language source of truth
191	        if !self.source_text.is_empty() {
192	            std::fs::write(skill_dir.join("procedures.md"), &self.source_text).map_err(|e| {
193	                AuthorError::Io {
194	                    path: skill_dir.join("procedures.md").display().to_string(),
195	                    source: e,
196	                }
197	            })?;
198	        }
199	
200	        Ok(skill_dir)
201	    }
202	
203	    /// Validate internal consistency of the authored skill.
204	    ///
205	    /// Checks:
206	    /// - All step names in plans reference a known action name.
207	    /// - No duplicate action names.
208	    pub fn validate(&self) -> AuthorResult<()> {
209	        let action_names: HashSet<&str> = self.actions.iter().map(|a| a.action.as_str()).collect();
210	
211	        // Check for duplicate action names.
212	        let mut seen = HashSet::new();
213	        for action in &self.actions {
214	            if !seen.insert(action.action.as_str()) {
215	                return Err(AuthorError::ValidationFailed {
216	                    message: format!("duplicate action name: `{}`", action.action),
217	                });
218	            }
219	        }
220	
221	        // Check plan step references.
222	        for plan in &self.plans {
223	            for step in &plan.steps {
224	                if !action_names.contains(step.as_str()) {
225	                    return Err(AuthorError::ValidationFailed {
226	                        message: format!(
227	                            "plan `{}` references unknown action `{}`; \
228	                             known actions: [{}]",
229	                            plan.goal,
230	                            step,
231	                            action_names.iter().cloned().collect::<Vec<_>>().join(", ")
232	                        ),
233	                    });
234	                }
235	            }
236	        }
237	
238	        Ok(())
239	    }
240	}
241	
242	// ─────────────────────────────────────────────────────────────────────────────
243	// ExtractionHints — caller-provided guidance for the authoring pipeline
244	// ─────────────────────────────────────────────────────────────────────────────
245	
246	/// Optional hints passed to the authoring pipeline to steer extraction.
247	#[derive(Debug, Clone, Default, Serialize, Deserialize)]
248	pub struct ExtractionHints {
249	    /// Suggested domain tags (merged with LLM-detected ones).
250	    pub domains: Vec<String>,
251	    /// Fluents the caller knows exist in the world model (seed for validation).
252	    pub known_fluents: Vec<String>,
253	    /// Maximum number of actions to extract.
254	    pub max_actions: Option<usize>,
255	    /// Maximum number of plan templates to extract.
256	    pub max_plans: Option<usize>,
257	}
258	
259	// ─────────────────────────────────────────────────────────────────────────────
260	// SkillAuthor
261	// ─────────────────────────────────────────────────────────────────────────────
262	
263	/// Orchestrates the multi-pass LLM extraction pipeline for skill authoring.
264	///
265	/// Construction succeeds even when the Candle backend is absent; the authoring
266	/// methods return `AuthorError::BackendUnavailable` in that case.  This lets
267	/// callers handle the case gracefully at runtime rather than at compile time.
268	pub struct SkillAuthor {
269	    /// Whether the LLM backend is available (Phase 26b Candle integration).
270	    llm_available: bool,
271	}
272	
273	impl std::fmt::Debug for SkillAuthor {
274	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
275	        f.debug_struct("SkillAuthor")
276	            .field("llm_available", &self.llm_available)
277	            .finish()
278	    }
279	}
280	
281	impl SkillAuthor {
282	    /// Create a new author.  Pass `llm_available = true` when the Candle
283	    /// backend has been initialised (Phase 26b).
284	    pub fn new(llm_available: bool) -> Self {
285	        Self { llm_available }
286	    }
287	
288	    /// Return whether the LLM backend is available.
289	    pub fn is_llm_available(&self) -> bool {
290	        self.llm_available
291	    }
292	
293	    /// Generate a complete skill from a natural language description.
294	    ///
295	    /// When the LLM backend is unavailable this returns a minimal stub skill
296	    /// with only the metadata populated so the caller can still save it and
297	    /// fill in the procedural files by hand.
298	    pub fn author_from_description(
299	        &self,
300	        id: &str,
301	        name: &str,
302	        description: &str,
303	        hints: ExtractionHints,
304	    ) -> AuthorResult<AuthoredSkill> {
305	        if !self.llm_available {
306	            // Return a stub — the caller can fill in files manually.
307	            return Ok(self.stub_skill(id, name, description, hints));
308	        }
309	
310	        // Full multi-pass pipeline (requires Phase 26b Candle backend).
311	        // Implemented here once the backend is wired; for now we fall back to
312	        // the stub path since we cannot call the LLM.
313	        //
314	        // Planned passes:
315	        // 1. concept_pass(description) → Vec<LabelTriple>
316	        // 2. action_pass(description, &triples) → Vec<SkillAction>
317	        // 3. plan_pass(description, &actions) → Vec<SkillPlan>
318	        // 4. rule_pass(description, &triples, &actions) → Vec<String>
319	        // 5. validate(&authored_skill)
320	        //
321	        // Each pass sends a focused prompt to the LLM and parses the JSON
322	        // response with brace-depth tracking to handle streaming tokens.
323	        tracing::warn!(
324	            skill_id = id,
325	            "LLM-assisted authoring is not yet fully wired to Phase 26b Candle backend; \
326	             returning stub skill"
327	        );
328	        Ok(self.stub_skill(id, name, description, hints))
329	    }
330	
331	    /// Re-generate structured skill files from an updated `procedures.md`.
332	    ///
333	    /// Useful when the user edits the natural language description after initial
334	    /// authoring.  The regeneration uses the same multi-pass pipeline as
335	    /// `author_from_description`.
336	    pub fn regenerate_from_procedures(
337	        &self,
338	        id: &str,
339	        name: &str,
340	        procedures_text: &str,
341	        hints: ExtractionHints,
342	    ) -> AuthorResult<AuthoredSkill> {
343	        self.author_from_description(id, name, procedures_text, hints)
344	    }
345	
346	    // ─── Internal helpers ────────────────────────────────────────────────────
347	
348	    /// Build a minimal stub skill with no procedural content.
349	    fn stub_skill(
350	        &self,
351	        id: &str,
352	        name: &str,
353	        description: &str,
354	        hints: ExtractionHints,
355	    ) -> AuthoredSkill {
356	        let domains = if hints.domains.is_empty() {
357	            vec!["general".to_string()]
358	        } else {
359	            hints.domains
360	        };
361	
362	        AuthoredSkill {
363	            manifest: SkillManifest {
364	                id: id.to_string(),
365	                name: name.to_string(),
366	                version: "0.1.0".to_string(),
367	                description: description.to_string(),
368	                domains,
369	                weight_size_bytes: 0,
370	                triples_file: None,
371	                rules_file: None,
372	                cli_tools: Vec::new(),
373	                wasm_tools: Vec::new(),
374	                tool_config: std::collections::HashMap::new(),
375	                actions_file: Some("actions.json".into()),
376	                plans_file: Some("plans.json".into()),
377	                procedures_file: Some("procedures.md".into()),
378	            },
379	            triples: Vec::new(),
380	            actions: Vec::new(),
381	            plans: Vec::new(),
382	            rules: Vec::new(),
383	            source_text: description.to_string(),
384	        }
385	    }
386	
387	    // ─── Static helpers for building skill components ────────────────────────
388	
389	    /// Build a `SkillAction` from raw parts.  Convenience for expert / Tier 3
390	    /// callers who want to construct actions programmatically.
391	    pub fn build_action(
392	        action: impl Into<String>,
393	        description: impl Into<String>,
394	        preconditions: Vec<String>,
395	        initiates: Vec<String>,
396	        terminates: Vec<String>,
397	    ) -> SkillAction {
398	        SkillAction {
399	            action: action.into(),
400	            description: description.into(),
401	            preconditions,
402	            effects: SkillEffects {
403	                initiates,
404	                terminates,
405	            },
406	            estimated_duration: super::ActionDuration::Fast,
407	        }
408	    }
409	
410	    /// Build a sequential `SkillPlan` from raw parts.
411	    pub fn build_sequential_plan(
412	        goal: impl Into<String>,
413	        steps: Vec<String>,
414	        preconditions: Vec<String>,
415	    ) -> SkillPlan {
416	        SkillPlan {
417	            goal: goal.into(),
418	            method: super::PlanMethod::Sequential,
419	            steps,
420	            preconditions,
421	            alternatives: Vec::new(),
422	            quality_gate: None,
423	        }
424	    }
425	}
