437	    fn sample_authored_skill() -> AuthoredSkill {
438	        let author = SkillAuthor::new(false);
439	        let hints = ExtractionHints {
440	            domains: vec!["code-review".into()],
441	            ..Default::default()
442	        };
443	        let mut skill = author
444	            .author_from_description("code-review", "Code Review", "review code", hints)
445	            .unwrap();
446	
447	        // Populate manually for tests.
448	        skill.actions = vec![
