466	            vec!["read_file".into(), "find_bugs".into()],
467	            vec!["file_available".into()],
468	        )];
469	        skill
470	    }
471	
472	    #[test]
473	    fn stub_skill_has_correct_metadata() {
474	        let author = SkillAuthor::new(false);
475	        let hints = ExtractionHints::default();
476	        let skill = author
477	            .author_from_description("my-skill", "My Skill", "does things", hints)
478	            .unwrap();
479	        assert_eq!(skill.manifest.id, "my-skill");
480	        assert_eq!(skill.manifest.name, "My Skill");
481	        assert_eq!(skill.manifest.version, "0.1.0");
482	    }
