490	    #[test]
491	    fn validation_fails_for_unknown_action_ref() {
492	        let mut skill = sample_authored_skill();
493	        skill.plans[0].steps.push("nonexistent_action".into());
494	        let err = skill.validate().unwrap_err();
495	        assert!(matches!(err, AuthorError::ValidationFailed { .. }));
496	    }
497	
498	    #[test]
499	    fn validation_fails_for_duplicate_action_name() {
500	        let mut skill = sample_authored_skill();
501	        skill.actions.push(skill.actions[0].clone()); // duplicate
502	        let err = skill.validate().unwrap_err();
503	        assert!(matches!(err, AuthorError::ValidationFailed { .. }));
504	    }
