506	    #[test]
507	    fn write_to_disk_creates_files() {
508	        let tmp = TempDir::new().unwrap();
509	        let skill = sample_authored_skill();
510	        let skill_dir = skill.write_to_disk(tmp.path()).unwrap();
511	
512	        assert!(skill_dir.join("skill.json").exists());
513	        assert!(skill_dir.join("actions.json").exists());
514	        assert!(skill_dir.join("plans.json").exists());
515	        assert!(skill_dir.join("procedures.md").exists());
516	    }
517	
518	    #[test]
519	    fn build_helpers_produce_correct_types() {
520	        let action = SkillAuthor::build_action(
521	            "step_a",
522	            "Do step A",
523	            vec!["pre_a".into()],
524	            vec!["post_a".into()],
525	            vec!["pre_a".into()],
526	        );
527	        assert_eq!(action.action, "step_a");
528	        assert_eq!(action.effects.initiates, vec!["post_a"]);
529	
530	        let plan = SkillAuthor::build_sequential_plan(
531	            "my_goal",
532	            vec!["step_a".into()],
533	            vec!["pre_a".into()],
534	        );
535	        assert_eq!(plan.goal, "my_goal");
536	        assert_eq!(plan.steps, vec!["step_a"]);
537	        assert_eq!(plan.method, super::super::PlanMethod::Sequential);
538	    }
539	
540	    // `SkillState` is not used inside this module at runtime, but verifying
541	    // it's accessible proves the import chain compiles correctly.
542	    #[test]
543	    fn skill_state_accessible() {
544	        assert_eq!(SkillState::Cold.to_string(), "Cold");
545	    }
546	}
