387	    // ─── Static helpers for building skill components ────────────────────────
388	
389	    /// Build a `SkillAction` from raw parts.  Convenience for expert / Tier 3
390	    /// callers who want to construct actions programmatically.
391	    pub fn build_action(
392	        action: impl Into<String>,
393	        description: impl Into<String>,
394	        preconditions: Vec<String>,
395	        initiates: Vec<String>,
396	        terminates: Vec<String>,
397	    ) -> SkillAction {
398	        SkillAction {
399	            action: action.into(),
400	            description: description.into(),
401	            preconditions,
402	            effects: SkillEffects {
403	                initiates,
404	                terminates,
405	            },
406	            estimated_duration: super::ActionDuration::Fast,
407	        }
408	    }
409	
410	    /// Build a sequential `SkillPlan` from raw parts.
411	    pub fn build_sequential_plan(
412	        goal: impl Into<String>,
413	        steps: Vec<String>,
414	        preconditions: Vec<String>,
415	    ) -> SkillPlan {
416	        SkillPlan {
417	            goal: goal.into(),
418	            method: super::PlanMethod::Sequential,
419	            steps,
420	            preconditions,
421	            alternatives: Vec::new(),
422	            quality_gate: None,
423	        }
424	    }
425	}
