1	//! Causal world model — Phase 15a.
2	//!
3	//! Explicit causal representation: cause-and-effect predicates, action schemas
4	//! with preconditions and effects, state transition prediction, and outcome
5	//! verification.  The causal model enables the agent to predict what will happen
6	//! before acting and to learn from the accuracy of its predictions.
7	
8	use std::collections::HashMap;
9	use std::fmt;
10	
11	use miette::Diagnostic;
12	use serde::{Deserialize, Serialize};
13	use thiserror::Error;
14	
15	use crate::engine::Engine;
16	use crate::graph::Triple;
17	use crate::provenance::DerivationKind;
18	use crate::symbol::SymbolId;
19	use crate::vsa::encode::encode_token;
20	use crate::vsa::ops::VsaOps;
21	use crate::vsa::HyperVec;
22	
23	// ═══════════════════════════════════════════════════════════════════════
24	// Error
25	// ═══════════════════════════════════════════════════════════════════════
26	
27	/// Errors specific to the causal reasoning subsystem.
28	#[derive(Debug, Error, Diagnostic)]
29	pub enum CausalError {
30	    #[error("action schema not found: {name}")]
31	    #[diagnostic(
32	        code(akh::agent::causal::schema_not_found),
33	        help("Register an action schema with `causal_manager.register_action_schema()`.")
34	    )]
35	    SchemaNotFound { name: String },
36	
37	    #[error("no applicable actions in current state")]
38	    #[diagnostic(
39	        code(akh::agent::causal::no_applicable),
40	        help("The current KG state does not satisfy any action preconditions.")
41	    )]
42	    NoApplicableActions,
43	
44	    #[error("pattern binding failed: unresolved variable `{variable}`")]
45	    #[diagnostic(
46	        code(akh::agent::causal::binding_failed),
47	        help("Ensure all variables in effects appear in preconditions.")
48	    )]
49	    BindingFailed { variable: String },
50	
51	    #[error("{0}")]
52	    #[diagnostic(
53	        code(akh::agent::causal::engine),
54	        help("An engine-level error occurred during causal reasoning.")
55	    )]
56	    Engine(Box<crate::error::AkhError>),
57	}
58	
59	impl From<crate::error::AkhError> for CausalError {
60	    fn from(e: crate::error::AkhError) -> Self {
61	        Self::Engine(Box::new(e))
62	    }
63	}
64	
65	/// Result alias for the causal subsystem.
66	pub type CausalResult<T> = std::result::Result<T, CausalError>;
67	
68	// ═══════════════════════════════════════════════════════════════════════
69	// CausalRelation
70	// ═══════════════════════════════════════════════════════════════════════
71	
72	/// Types of causal relation between entities or events.
73	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
74	pub enum CausalRelation {
75	    /// A causes B (sufficient condition).
76	    Causes,
77	    /// A enables B (necessary but not sufficient).
78	    Enables,
79	    /// A prevents B (if A then not B).
80	    Prevents,
81	    /// A inhibits B (weakens but doesn't fully prevent).
82	    Inhibits,
83	}
84	
85	impl CausalRelation {
86	    pub fn as_label(&self) -> &'static str {
87	        match self {
88	            Self::Causes => "causes",
89	            Self::Enables => "enables",
90	            Self::Prevents => "prevents",
91	            Self::Inhibits => "inhibits",
92	        }
93	    }
94	
95	    pub fn from_label(s: &str) -> Option<Self> {
96	        match s {
97	            "causes" => Some(Self::Causes),
98	            "enables" => Some(Self::Enables),
99	            "prevents" => Some(Self::Prevents),
100	            "inhibits" => Some(Self::Inhibits),
101	            _ => None,
102	        }
103	    }
104	}
105	
106	impl fmt::Display for CausalRelation {
107	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
108	        f.write_str(self.as_label())
109	    }
110	}
111	
112	// ═══════════════════════════════════════════════════════════════════════
113	// CausalPredicates
114	// ═══════════════════════════════════════════════════════════════════════
115	
116	/// Well-known KG predicates for causal reasoning (namespace: `causal:`).
117	#[derive(Debug, Clone)]
118	pub struct CausalPredicates {
119	    pub causes: SymbolId,
120	    pub enables: SymbolId,
121	    pub prevents: SymbolId,
122	    pub inhibits: SymbolId,
123	    pub has_precondition: SymbolId,
124	    pub has_effect: SymbolId,
125	    pub has_expected_outcome: SymbolId,
126	    pub causal_strength: SymbolId,
127	}
128	
129	impl CausalPredicates {
130	    /// Resolve or create all causal predicates.
131	    pub fn init(engine: &Engine) -> CausalResult<Self> {
132	        Ok(Self {
133	            causes: engine.resolve_or_create_relation("causal:causes")?,
134	            enables: engine.resolve_or_create_relation("causal:enables")?,
135	            prevents: engine.resolve_or_create_relation("causal:prevents")?,
136	            inhibits: engine.resolve_or_create_relation("causal:inhibits")?,
137	            has_precondition: engine.resolve_or_create_relation("causal:has-precondition")?,
138	            has_effect: engine.resolve_or_create_relation("causal:has-effect")?,
139	            has_expected_outcome: engine
140	                .resolve_or_create_relation("causal:has-expected-outcome")?,
141	            causal_strength: engine.resolve_or_create_relation("causal:causal-strength")?,
142	        })
143	    }
144	
145	    /// Return the predicate SymbolId for a given relation type.
146	    pub fn predicate_for(&self, relation: CausalRelation) -> SymbolId {
147	        match relation {
148	            CausalRelation::Causes => self.causes,
149	            CausalRelation::Enables => self.enables,
150	            CausalRelation::Prevents => self.prevents,
151	            CausalRelation::Inhibits => self.inhibits,
152	        }
153	    }
154	}
155	
156	// ═══════════════════════════════════════════════════════════════════════
157	// Pattern & Effect Types
158	// ═══════════════════════════════════════════════════════════════════════
159	
160	/// An element in a causal pattern: concrete symbol, named variable, or wildcard.
161	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
162	pub enum PatternElement {
163	    /// A specific SymbolId.
164	    Concrete(SymbolId),
165	    /// A named variable bound during matching.
166	    Variable(String),
167	    /// Match anything.
168	    Wildcard,
169	}
170	
171	impl PatternElement {
172	    /// Resolve this element against a binding environment.
173	    pub fn resolve(&self, bindings: &HashMap<String, SymbolId>) -> Option<SymbolId> {
174	        match self {
175	            Self::Concrete(id) => Some(*id),
176	            Self::Variable(name) => bindings.get(name).copied(),
177	            Self::Wildcard => None,
178	        }
179	    }
180	
181	    /// Check whether this element matches a concrete SymbolId,
182	    /// potentially adding a binding.
183	    pub fn matches(
184	        &self,
185	        actual: SymbolId,
186	        bindings: &mut HashMap<String, SymbolId>,
187	    ) -> bool {
188	        match self {
189	            Self::Concrete(id) => *id == actual,
190	            Self::Variable(name) => {
191	                if let Some(&bound) = bindings.get(name) {
192	                    bound == actual
193	                } else {
194	                    bindings.insert(name.clone(), actual);
195	                    true
196	                }
197	            }
198	            Self::Wildcard => true,
199	        }
200	    }

