12	/// Agent tool that triggers forward-chaining rule inference.
13	pub struct InferRulesTool;
14	
15	impl Tool for InferRulesTool {
16	    fn signature(&self) -> ToolSignature {
17	        ToolSignature {
18	            name: "infer_rules".into(),
19	            description: "Run forward-chaining inference rules to derive new triples.".into(),
20	            parameters: vec![
21	                ToolParam {
22	                    name: "max_iterations".into(),
23	                    description: "Maximum forward-chaining iterations (default: 5).".into(),
24	                    required: false,
25	                },
26	                ToolParam {
27	                    name: "min_confidence".into(),
28	                    description: "Minimum confidence for derived triples (default: 0.1).".into(),
29	                    required: false,
30	                },
31	                ToolParam {
32	                    name: "cleanup".into(),
33	                    description: "Remove contaminated is-a/child-of triples before inference \
34	                                  (true/false, default: false). Use to retroactively purge \
35	                                  cross-domain type-hierarchy pollution from prior inference \
36	                                  bugs (e.g. agent identities linked to CI runners or storage \
37	                                  nodes)."
38	                        .into(),
39	                    required: false,
40	                },
41	            ],
42	        }
43	    }
44	
45	    fn execute(&self, engine: &Engine, input: ToolInput) -> AgentResult<ToolOutput> {
46	        let max_iterations = input
47	            .get("max_iterations")
48	            .and_then(|s| s.parse::<usize>().ok())
49	            .unwrap_or(5);
50	        let min_confidence = input
51	            .get("min_confidence")
52	            .and_then(|s| s.parse::<f32>().ok())
53	            .unwrap_or(0.1);
54	        let run_cleanup = input
55	            .get("cleanup")
56	            .map(|s| matches!(s, "true" | "1" | "yes"))
57	            .unwrap_or(false);
58	
59	        let mut lines = Vec::new();
60	
61	        if run_cleanup {
62	            let purged = engine.purge_contaminated_inferences()?;
63	            if purged > 0 {
64	                lines.push(format!(
65	                    "Cleanup: removed {purged} contaminated is-a/child-of triple(s)."
66	                ));
67	            } else {
68	                lines.push("Cleanup: no contaminated triples found.".into());
69	            }
70	        }
71	
72	        let config = RuleEngineConfig {
73	            max_iterations,
74	            min_confidence,
75	            ..Default::default()
76	        };
77	
78	        let result = engine.run_rules(config)?;
79	
80	        lines.push(format!(
81	            "Derived {} new triple(s) in {} iteration(s){}",
82	            result.derived.len(),
83	            result.iterations,
84	            if result.reached_fixpoint {
85	                " (fixpoint reached)"
86	            } else {
87	                ""
88	            },
89	        ));
90	
91	        for (rule, count) in &result.rule_stats {
92	            if *count > 0 {
93	                lines.push(format!("  {rule}: {count} derivation(s)"));
94	            }
95	        }
96	
97	        let symbols: Vec<_> = result
98	            .derived
99	            .iter()
100	            .flat_map(|dt| [dt.triple.subject, dt.triple.predicate, dt.triple.object])
101	            .collect();
102	
103	        Ok(ToolOutput::ok_with_symbols(lines.join("\n"), symbols))
104	    }
105	
106	    fn manifest(&self) -> ToolManifest {
107	        ToolManifest {
108	            name: "infer_rules".into(),
109	            description: "Forward-chaining inference — derives new triples from rules.".into(),
110	            parameters: vec![
111	                ToolParamSchema::optional(
112	                    "max_iterations",
113	                    "Maximum forward-chaining iterations (default: 5).",
114	                ),
115	                ToolParamSchema::optional(
116	                    "min_confidence",
117	                    "Minimum confidence for derived triples (default: 0.1).",
118	                ),
119	                ToolParamSchema::optional(
120	                    "cleanup",
121	                    "Remove contaminated is-a/child-of triples before inference \
122	                     (true/false, default: false).",
123	                ),
124	            ],
125	            danger: DangerInfo {
126	                level: DangerLevel::Safe,
127	                capabilities: HashSet::from([
128	                    Capability::Reason,
129	                    Capability::ReadKg,
130	                    Capability::WriteKg,
131	                ]),
132	                description: "Forward-chaining inference — derives new triples from rules.".into(),
133	                shadow_triggers: vec![],
134	            },
135	            source: ToolSource::Native,
136	        }
137	    }
138	}
