1	//! Skill quality metrics — Phase 30e.
2	//!
3	//! Tracks per-skill effectiveness so the agent can:
4	//! - Surface stale/ineffective skills to the user
5	//! - Suggest deactivation when a skill is unused or underperforming
6	//! - Prioritise refinements for the most frequently failing skills
7	//!
8	//! Metrics are kept in memory and can be persisted as KG triples with
9	//! `skill:quality_*` predicates.
10	//!
11	//! # Staleness detection
12	//!
13	//! A skill is considered *stale* when it hasn't been used for `stale_days`
14	//! days AND has a triple coverage below `min_coverage`.  Stale skills are
15	//! candidates for deactivation to free the memory budget.
16	
17	use std::collections::HashMap;
18	
19	use serde::{Deserialize, Serialize};
20	
21	// ─────────────────────────────────────────────────────────────────────────────
22	// FailureMode
23	// ─────────────────────────────────────────────────────────────────────────────
24	
25	/// A recurring failure pattern observed during skill execution.
26	#[derive(Debug, Clone, Serialize, Deserialize)]
27	pub struct FailureMode {
28	    /// The action that failed.
29	    pub action: String,
30	    /// Category of failure.
31	    pub failure_type: String,
32	    /// How many times this failure has been recorded.
33	    pub count: u32,
34	    /// Unix timestamp of the most recent occurrence.
35	    pub last_occurrence: u64,
36	}
37	
38	// ─────────────────────────────────────────────────────────────────────────────
39	// SkillQuality
40	// ─────────────────────────────────────────────────────────────────────────────
41	
42	/// Per-skill quality metrics.
43	#[derive(Debug, Clone, Serialize, Deserialize)]
44	pub struct SkillQuality {
45	    /// Skill identifier.
46	    pub skill_id: String,
47	
48	    /// Plans completed successfully / plans attempted.
49	    pub success_rate: f32,
50	    /// Total plan executions (completed + failed).
51	    pub total_executions: u32,
52	    /// Plans that completed successfully.
53	    pub successful_executions: u32,
54	
55	    /// Recurring failure patterns.
56	    pub failure_modes: Vec<FailureMode>,
57	
58	    /// Per-rule hit rates: rule name → fraction of inferences it participated in.
59	    pub rule_hit_rates: HashMap<String, f32>,
60	    /// Total inference passes across all rules.
61	    pub total_inference_passes: u64,
62	
63	    /// Fraction of the skill's triples that have been queried at least once.
64	    pub triple_coverage: f32,
65	    /// Number of distinct triples queried.
66	    pub triples_queried: usize,
67	    /// Total triples the skill declared.
68	    pub triples_total: usize,
69	
70	    /// Unix timestamp of the last successful execution (None if never used).
71	    pub last_used: Option<u64>,
72	
73	    /// How many refinement suggestions are currently pending.
74	    pub refinements_pending: u32,
75	    /// How many refinements have been applied to this skill.
76	    pub refinements_applied: u32,
77	}
78	
79	impl SkillQuality {
80	    /// Create a fresh quality record for a skill.
81	    pub fn new(skill_id: impl Into<String>, triples_total: usize) -> Self {
82	        Self {
83	            skill_id: skill_id.into(),
84	            success_rate: 0.0,
85	            total_executions: 0,
86	            successful_executions: 0,
87	            failure_modes: Vec::new(),
88	            rule_hit_rates: HashMap::new(),
89	            total_inference_passes: 0,
90	            triple_coverage: 0.0,
91	            triples_queried: 0,
92	            triples_total,
93	            last_used: None,
94	            refinements_pending: 0,
95	            refinements_applied: 0,
96	        }
97	    }
98	
99	    // ─── Mutation helpers ────────────────────────────────────────────────────
100	
101	    /// Record a successful plan execution.
102	    pub fn record_success(&mut self) {
103	        self.total_executions += 1;
104	        self.successful_executions += 1;
105	        self.recompute_success_rate();
106	        let now = now_secs();
107	        self.last_used = Some(now);
108	    }
109	
110	    /// Record a failed plan execution.
111	    pub fn record_failure(&mut self, action: &str, failure_type: &str) {
112	        self.total_executions += 1;
113	        self.recompute_success_rate();
114	
115	        let now = now_secs();
116	        if let Some(mode) = self
117	            .failure_modes
118	            .iter_mut()
119	            .find(|m| m.action == action && m.failure_type == failure_type)
120	        {
121	            mode.count += 1;
122	            mode.last_occurrence = now;
123	        } else {
124	            self.failure_modes.push(FailureMode {
125	                action: action.to_string(),
126	                failure_type: failure_type.to_string(),
127	                count: 1,
128	                last_occurrence: now,
129	            });
130	        }
131	    }
132	
133	    /// Record that a specific inference rule fired during reasoning.
134	    pub fn record_rule_hit(&mut self, rule_name: &str) {
135	        self.total_inference_passes += 1;
136	        let hits = self
137	            .rule_hit_rates
138	            .entry(rule_name.to_string())
139	            .or_insert(0.0);
140	        // Running average: new_rate = (old_rate * (n-1) + 1) / n
141	        let n = self.total_inference_passes as f32;
142	        *hits = (*hits * (n - 1.0) + 1.0) / n;
143	    }
144	
145	    /// Record that a rule pass occurred but this rule did NOT fire.
146	    pub fn record_rule_miss(&mut self, rule_name: &str) {
147	        self.total_inference_passes += 1;
148	        let hits = self
149	            .rule_hit_rates
150	            .entry(rule_name.to_string())
151	            .or_insert(0.0);
152	        let n = self.total_inference_passes as f32;
153	        // Rule did not fire: hit contribution is 0.
154	        *hits = *hits * (n - 1.0) / n;
155	    }
156	
157	    /// Record that a triple was queried, updating coverage.
158	    pub fn record_triple_query(&mut self, is_new_triple: bool) {
159	        if is_new_triple {
160	            self.triples_queried += 1;
161	        }
162	        self.recompute_coverage();
163	    }
164	
165	    /// Update the pending refinements count.
166	    pub fn set_refinements_pending(&mut self, count: u32) {
167	        self.refinements_pending = count;
168	    }
169	
170	    /// Record that a refinement was applied.
171	    pub fn record_refinement_applied(&mut self) {
172	        self.refinements_applied += 1;
173	        if self.refinements_pending > 0 {
174	            self.refinements_pending -= 1;
175	        }
176	    }
177	
178	    // ─── Derived properties ──────────────────────────────────────────────────
179	
180	    /// Return the most common failure mode, if any.
181	    pub fn top_failure_mode(&self) -> Option<&FailureMode> {
182	        self.failure_modes.iter().max_by_key(|m| m.count)
183	    }
184	
185	    /// Return rules whose hit rate is below `threshold` (likely dead rules).
186	    pub fn low_hit_rate_rules(&self, threshold: f32) -> Vec<(&str, f32)> {
187	        self.rule_hit_rates
188	            .iter()
189	            .filter(|(_, rate)| **rate < threshold)
190	            .map(|(name, rate)| (name.as_str(), *rate))
191	            .collect()
192	    }
193	
194	    // ─── Internal ────────────────────────────────────────────────────────────
195	
196	    fn recompute_success_rate(&mut self) {
197	        if self.total_executions == 0 {
198	            self.success_rate = 0.0;
199	        } else {
200	            self.success_rate = self.successful_executions as f32 / self.total_executions as f32;
201	        }
202	    }
203	
204	    fn recompute_coverage(&mut self) {
205	        if self.triples_total == 0 {
206	            self.triple_coverage = 1.0; // vacuously full coverage
207	        } else {
208	            self.triple_coverage =
209	                self.triples_queried.min(self.triples_total) as f32 / self.triples_total as f32;
210	        }
211	    }
212	}
213	
214	// ─────────────────────────────────────────────────────────────────────────────
215	// StalenessConfig
216	// ─────────────────────────────────────────────────────────────────────────────
217	
218	/// Configuration for staleness detection.
219	#[derive(Debug, Clone, Serialize, Deserialize)]
220	pub struct StalenessConfig {
221	    /// Number of days without use before a skill is considered stale.
222	    pub stale_days: u32,
223	    /// Minimum triple coverage below which a skill is considered under-utilised.
224	    pub min_coverage: f32,
225	    /// Minimum success rate below which a skill is flagged for review.
226	    pub min_success_rate: f32,
227	}
228	
229	impl Default for StalenessConfig {
230	    fn default() -> Self {
231	        Self {
232	            stale_days: 30,
233	            min_coverage: 0.1,
234	            min_success_rate: 0.5,
235	        }
236	    }
237	}
238	
239	// ─────────────────────────────────────────────────────────────────────────────
240	// QualityRegistry
241	// ─────────────────────────────────────────────────────────────────────────────
242	
243	/// Registry of quality metrics for all known skills.
244	#[derive(Debug, Default)]
245	pub struct QualityRegistry {
246	    records: HashMap<String, SkillQuality>,
247	    config: StalenessConfig,
248	}
249	
250	impl QualityRegistry {
251	    /// Create an empty registry with default staleness config.
252	    pub fn new() -> Self {
253	        Self::default()
254	    }
255	
256	    /// Create a registry with custom staleness config.
257	    pub fn with_config(config: StalenessConfig) -> Self {
258	        Self {
259	            records: HashMap::new(),
260	            config,
261	        }
262	    }
263	
264	    /// Ensure a quality record exists for `skill_id`.
265	    pub fn ensure(&mut self, skill_id: &str, triples_total: usize) {
266	        self.records
267	            .entry(skill_id.to_string())
268	            .or_insert_with(|| SkillQuality::new(skill_id, triples_total));
269	    }
270	
271	    /// Get an immutable reference to a skill's quality record.
272	    pub fn get(&self, skill_id: &str) -> Option<&SkillQuality> {
273	        self.records.get(skill_id)
274	    }
275	
276	    /// Get a mutable reference to a skill's quality record.
277	    pub fn get_mut(&mut self, skill_id: &str) -> Option<&mut SkillQuality> {
278	        self.records.get_mut(skill_id)
279	    }
280	
281	    /// Return skill IDs that are stale under the current config.
282	    pub fn stale_skills(&self) -> Vec<&str> {
283	        let threshold_secs = self.config.stale_days as u64 * 86_400;
284	        let now = now_secs();
285	
286	        self.records
287	            .values()
288	            .filter(|q| {
289	                let stale_by_time = match q.last_used {
290	                    None => true, // never used
291	                    Some(last) => now.saturating_sub(last) > threshold_secs,
292	                };
293	                let low_coverage = q.triple_coverage < self.config.min_coverage;
294	                stale_by_time && low_coverage
295	            })
296	            .map(|q| q.skill_id.as_str())
297	            .collect()
298	    }
299	
300	    /// Return skill IDs with success rate below the configured threshold.
301	    pub fn underperforming_skills(&self) -> Vec<&str> {
302	        self.records
303	            .values()
304	            .filter(|q| q.total_executions > 0 && q.success_rate < self.config.min_success_rate)
305	            .map(|q| q.skill_id.as_str())
306	            .collect()
307	    }
308	
309	    /// Return all quality records.
310	    pub fn all(&self) -> Vec<&SkillQuality> {
311	        self.records.values().collect()
312	    }
313	
314	    /// Remove a skill's quality record (e.g. on full uninstall).
315	    pub fn remove(&mut self, skill_id: &str) {
316	        self.records.remove(skill_id);
317	    }
318	}
319	
320	// ─────────────────────────────────────────────────────────────────────────────
321	// Helpers
322	// ─────────────────────────────────────────────────────────────────────────────
323	
324	fn now_secs() -> u64 {
325	    std::time::SystemTime::now()
326	        .duration_since(std::time::UNIX_EPOCH)
327	        .unwrap_or_default()
328	        .as_secs()
329	}
330	
331	// ─────────────────────────────────────────────────────────────────────────────
332	// Tests
333	// ─────────────────────────────────────────────────────────────────────────────
334	
335	#[cfg(test)]
336	mod tests {
337	    use super::*;
338	
339	    #[test]
340	    fn success_rate_tracking() {
341	        let mut q = SkillQuality::new("my-skill", 10);
342	        q.record_success();
343	        q.record_success();
344	        q.record_failure("act_a", "precondition_unmet");
345	        assert_eq!(q.total_executions, 3);
346	        assert!((q.success_rate - 2.0 / 3.0).abs() < 1e-6);
347	    }
348	
349	    #[test]
350	    fn failure_mode_dedup() {
351	        let mut q = SkillQuality::new("s", 5);
352	        q.record_failure("act_a", "timeout");
353	        q.record_failure("act_a", "timeout");
354	        q.record_failure("act_b", "precondition_unmet");
355	        assert_eq!(q.failure_modes.len(), 2);
356	        let top = q.top_failure_mode().unwrap();
357	        assert_eq!(top.action, "act_a");
358	        assert_eq!(top.count, 2);
359	    }
360	
361	    #[test]
362	    fn triple_coverage() {
363	        let mut q = SkillQuality::new("s", 4);
364	        q.record_triple_query(true);
365	        q.record_triple_query(true);
366	        assert!((q.triple_coverage - 0.5).abs() < 1e-6);
367	        // Querying same triple again (not new) doesn't change coverage.
368	        q.record_triple_query(false);
369	        assert!((q.triple_coverage - 0.5).abs() < 1e-6);
370	    }
371	
372	    #[test]
373	    fn rule_hit_rates() {
374	        let mut q = SkillQuality::new("s", 0);
375	        q.record_rule_hit("rule-0");
376	        q.record_rule_hit("rule-0");
377	        q.record_rule_miss("rule-1");
378	        // rule-0 hit 2 out of 3 passes
379	        let rate = q.rule_hit_rates["rule-0"];
380	        assert!(rate > 0.0 && rate <= 1.0, "rate={rate}");
381	    }
382	
383	    #[test]
384	    fn staleness_detection() {
385	        let mut reg = QualityRegistry::with_config(StalenessConfig {
386	            stale_days: 1,
387	            min_coverage: 0.5,
388	            min_success_rate: 0.5,
389	        });
390	        reg.ensure("never-used", 100);
391	        // A skill never used has coverage 0 < 0.5, so stale.
392	        let stale = reg.stale_skills();
393	        assert!(stale.contains(&"never-used"));
394	    }
395	
396	    #[test]
397	    fn underperforming_skills() {
398	        let mut reg = QualityRegistry::new();
399	        reg.ensure("bad-skill", 5);
400	        let q = reg.get_mut("bad-skill").unwrap();
401	        q.record_failure("act", "timeout");
402	        q.record_failure("act", "timeout");
403	
404	        let under = reg.underperforming_skills();
405	        assert!(under.contains(&"bad-skill"));
406	    }
407	
408	    #[test]
409	    fn refinement_tracking() {
410	        let mut q = SkillQuality::new("s", 0);
411	        q.set_refinements_pending(3);
412	        q.record_refinement_applied();
413	        assert_eq!(q.refinements_pending, 2);
414	        assert_eq!(q.refinements_applied, 1);
415	    }
416	}
