37	#[derive(Debug, Error, Diagnostic)]
38	pub enum AuthorError {
39	    #[error("LLM backend unavailable: {reason}")]
40	    #[diagnostic(
41	        code(akh::skill::author::backend_unavailable),
42	        help(
43	            "LLM-assisted skill authoring requires the `candle-backend` feature (Phase 26b). \
44	             Build with `--features candle-backend` or author the skill files by hand."
45	        )
46	    )]
47	    BackendUnavailable { reason: String },
48	
49	    #[error("extraction pass failed ({pass}): {message}")]
50	    #[diagnostic(
51	        code(akh::skill::author::extraction_failed),
52	        help(
53	            "The LLM could not extract structured data from the provided description. \
54	             Try rephrasing with clearer step descriptions and explicit preconditions."
55	        )
56	    )]
57	    ExtractionFailed { pass: String, message: String },
58	
59	    #[error("validation failed: {message}")]
60	    #[diagnostic(
61	        code(akh::skill::author::validation_failed),
62	        help(
63	            "The generated skill failed internal consistency checks. \
64	             Review the generated files and fix the listed issues."
65	        )
66	    )]
67	    ValidationFailed { message: String },
68	
69	    #[error("I/O error writing skill to {path}: {source}")]
70	    #[diagnostic(
71	        code(akh::skill::author::io),
72	        help("Ensure the target skills directory exists and is writable.")
73	    )]
74	    Io {
75	        path: String,
76	        #[source]
77	        source: std::io::Error,
78	    },
79	
80	    #[error("serialization error: {message}")]
81	    #[diagnostic(
82	        code(akh::skill::author::serialize),
83	        help("Internal JSON serialization failure; this is a bug.")
84	    )]
85	    Serialize { message: String },
86	}
