156	// ═══════════════════════════════════════════════════════════════════════
157	// Pattern & Effect Types
158	// ═══════════════════════════════════════════════════════════════════════
159	
160	/// An element in a causal pattern: concrete symbol, named variable, or wildcard.
161	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
162	pub enum PatternElement {
163	    /// A specific SymbolId.
164	    Concrete(SymbolId),
165	    /// A named variable bound during matching.
166	    Variable(String),
167	    /// Match anything.
168	    Wildcard,
169	}
170	
171	impl PatternElement {
172	    /// Resolve this element against a binding environment.
173	    pub fn resolve(&self, bindings: &HashMap<String, SymbolId>) -> Option<SymbolId> {
174	        match self {
175	            Self::Concrete(id) => Some(*id),
176	            Self::Variable(name) => bindings.get(name).copied(),
177	            Self::Wildcard => None,
178	        }
179	    }
180	
181	    /// Check whether this element matches a concrete SymbolId,
182	    /// potentially adding a binding.
183	    pub fn matches(
184	        &self,
185	        actual: SymbolId,
186	        bindings: &mut HashMap<String, SymbolId>,
187	    ) -> bool {
188	        match self {
189	            Self::Concrete(id) => *id == actual,
190	            Self::Variable(name) => {
191	                if let Some(&bound) = bindings.get(name) {
192	                    bound == actual
193	                } else {
194	                    bindings.insert(name.clone(), actual);
195	                    true
196	                }
197	            }
198	            Self::Wildcard => true,
199	        }
200	    }
201	}
202	
203	/// A pattern for matching precondition triples.
204	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
205	pub struct CausalPattern {
206	    pub subject: PatternElement,
207	    pub predicate: PatternElement,
208	    pub object: PatternElement,
209	    /// If true, the pattern must NOT match (negation-as-failure).
210	    pub negated: bool,
211	}
212	
213	impl CausalPattern {
214	    /// Check whether this pattern matches any triple in the KG.
215	    pub fn matches_any(
216	        &self,
217	        triples: &[Triple],
218	        bindings: &mut HashMap<String, SymbolId>,
219	    ) -> bool {
220	        let found = triples.iter().any(|t| {
221	            let mut trial_bindings = bindings.clone();
222	            self.subject.matches(t.subject, &mut trial_bindings)
223	                && self.predicate.matches(t.predicate, &mut trial_bindings)
224	                && self.object.matches(t.object, &mut trial_bindings)
225	                && {
226	                    // Only commit bindings if all three matched.
227	                    *bindings = trial_bindings;
228	                    true
229	                }
230	        });
231	        if self.negated { !found } else { found }
232	    }
233	}
234	
235	/// The kind of effect an action has on the KG.
236	#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
237	pub enum EffectKind {
238	    /// Triple is added to the KG.
239	    Assert,
240	    /// Triple is removed from the KG.
241	    Retract,
242	    /// Confidence of an existing triple is modified by delta.
243	    ModifyConfidence { delta: f32 },
244	}
245	
246	/// An effect that an action has on the KG state.
247	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
248	pub struct CausalEffect {
249	    pub kind: EffectKind,
250	    pub subject: PatternElement,
251	    pub predicate: PatternElement,
252	    pub object: PatternElement,
253	    /// Expected confidence of the resulting triple.
254	    pub confidence: f32,
255	}
