257	// ═══════════════════════════════════════════════════════════════════════
258	// ActionSchema
259	// ═══════════════════════════════════════════════════════════════════════
260	
261	/// An action schema describing what a tool/action does to world state.
262	#[derive(Debug, Clone, Serialize, Deserialize)]
263	pub struct ActionSchema {
264	    /// Symbol for the action (usually a tool-name entity).
265	    pub action_id: SymbolId,
266	    /// Human-readable name (matches tool name).
267	    pub name: String,
268	    /// Preconditions: triples that must hold for this action to be applicable.
269	    pub preconditions: Vec<CausalPattern>,
270	    /// Effects: triples that will be added/removed after execution.
271	    pub effects: Vec<CausalEffect>,
272	    /// Observed success rate (updated after each execution).
273	    pub success_rate: f32,
274	    /// Number of times this action has been executed.
275	    pub execution_count: u32,
276	}
277	
278	impl ActionSchema {
279	    /// Check whether all preconditions are satisfied against the current KG state.
280	    pub fn is_applicable(&self, triples: &[Triple]) -> bool {
281	        let mut bindings = HashMap::new();
282	        self.preconditions
283	            .iter()
284	            .all(|p| p.matches_any(triples, &mut bindings))
285	    }
286	
287	    /// Predict the state transition from applying this action.
288	    pub fn predict_effects(
289	        &self,
290	        triples: &[Triple],
291	    ) -> CausalResult<StateTransition> {
292	        let mut bindings = HashMap::new();
293	        for p in &self.preconditions {
294	            p.matches_any(triples, &mut bindings);
295	        }
296	
297	        let mut assertions = Vec::new();
298	        let mut retractions = Vec::new();
299	        let mut confidence_changes = Vec::new();
300	
301	        for eff in &self.effects {
302	            let s = eff.subject.resolve(&bindings);
303	            let p = eff.predicate.resolve(&bindings);
304	            let o = eff.object.resolve(&bindings);
305	
306	            // Skip effects with unresolvable variables.
307	            let (Some(s), Some(p), Some(o)) = (s, p, o) else {
308	                continue;
309	            };
310	
311	            match eff.kind {
312	                EffectKind::Assert => assertions.push((s, p, o)),
313	                EffectKind::Retract => retractions.push((s, p, o)),
314	                EffectKind::ModifyConfidence { delta } => {
315	                    confidence_changes.push((s, p, o, delta));
316	                }
317	            }
318	        }
319	
320	        let now = std::time::SystemTime::now()
321	            .duration_since(std::time::UNIX_EPOCH)
322	            .unwrap_or_default()
323	            .as_secs();
324	
325	        Ok(StateTransition {
326	            action_id: self.action_id,
327	            assertions,
328	            retractions,
329	            confidence_changes,
330	            verified: None,
331	            timestamp: now,
332	        })
333	    }
334	}
