387	// CausalManager
388	// ═══════════════════════════════════════════════════════════════════════
389	
390	/// Manages the causal world model: action schemas, predictions, verification.
391	#[derive(Debug, Clone, Default, Serialize, Deserialize)]
392	pub struct CausalManager {
393	    /// Registered action schemas, keyed by name.
394	    pub schemas: HashMap<String, ActionSchema>,
395	    /// Lazily initialized predicates (not serialized).
396	    #[serde(skip)]
397	    predicates: Option<CausalPredicates>,
398	    /// Lazily initialized role vectors (not serialized).
399	    #[serde(skip)]
400	    role_vectors: Option<CausalRoleVectors>,
401	}
402	
403	impl CausalManager {
404	    /// Create a new causal manager and initialize KG predicates.
405	    pub fn new(engine: &Engine) -> CausalResult<Self> {
406	        let mut mgr = Self::default();
407	        mgr.ensure_init(engine)?;
408	        Ok(mgr)
409	    }
410	
411	    /// Ensure predicates and role vectors are initialized.
412	    pub fn ensure_init(&mut self, engine: &Engine) -> CausalResult<()> {
413	        if self.predicates.is_none() {
414	            self.predicates = Some(CausalPredicates::init(engine)?);
415	        }
416	        if self.role_vectors.is_none() {
417	            self.role_vectors = Some(CausalRoleVectors::new(engine.ops()));
418	        }
419	        Ok(())
420	    }
421	
422	    /// Restore from durable store.
423	    pub fn restore(engine: &Engine) -> CausalResult<Self> {
424	        let data = engine
425	            .store()
426	            .get_meta(b"agent:causal_manager")
427	            .map_err(|e| CausalError::Engine(Box::new(e.into())))?;
428	        match data {
429	            Some(bytes) if !bytes.is_empty() => {
430	                let mut mgr: Self =
431	                    bincode::deserialize(&bytes).map_err(|e| CausalError::Engine(Box::new(
432	                        crate::error::AkhError::Store(crate::error::StoreError::Serialization {
433	                            message: format!("causal manager deserialize: {e}"),
434	                        }),
435	                    )))?;
436	                mgr.ensure_init(engine)?;
437	                Ok(mgr)
438	            }
439	            _ => Self::new(engine),
440	        }
441	    }
442	
443	    /// Persist to durable store.
444	    pub fn persist(&self, engine: &Engine) -> CausalResult<()> {
445	        let bytes = bincode::serialize(self).map_err(|e| {
446	            CausalError::Engine(Box::new(crate::error::AkhError::Store(
447	                crate::error::StoreError::Serialization {
448	                    message: format!("causal manager serialize: {e}"),
449	                },
450	            )))
451	        })?;
452	        engine
453	            .store()
454	            .put_meta(b"agent:causal_manager", &bytes)
