476	    /// Remove all action schemas registered by a specific skill.
477	    ///
478	    /// Schemas registered from skills use the naming convention
479	    /// `"skill/{skill_id}/{action_name}"`.  Returns the number removed.
480	    pub fn remove_schemas_by_skill(&mut self, skill_id: &str) -> usize {
481	        let prefix = format!("skill/{skill_id}/");
482	        let before = self.schemas.len();
483	        self.schemas.retain(|name, _| !name.starts_with(&prefix));
484	        before - self.schemas.len()
485	    }
