487	    /// Bootstrap action schemas from the tool registry.
488	    ///
489	    /// Creates a minimal schema for each tool with no preconditions
490	    /// and a single generic "executed" effect.  These are refined over
491	    /// time as predictions are verified.
492	    pub fn bootstrap_schemas_from_tools(
493	        &mut self,
494	        tool_names: &[String],
495	        engine: &Engine,
496	    ) -> CausalResult<usize> {
497	        let mut count = 0;
498	        for name in tool_names {
499	            if self.schemas.contains_key(name) {
500	                continue;
501	            }
502	            let action_id = engine.resolve_or_create_entity(&format!("tool:{name}"))?;
503	            let schema = ActionSchema {
504	                action_id,
505	                name: name.clone(),
506	                preconditions: Vec::new(),
507	                effects: Vec::new(),
508	                success_rate: 0.5, // uninformed prior
509	                execution_count: 0,
510	            };
511	            self.schemas.insert(name.clone(), schema);
512	            count += 1;
513	        }
514	        Ok(count)
515	    }
