544	    /// Verify a prediction against the actual state after execution.
545	    /// Returns true if the prediction was accurate.
546	    pub fn verify_prediction(
547	        &self,
548	        transition: &StateTransition,
549	        engine: &Engine,
550	    ) -> bool {
551	        let triples = engine.all_triples();
552	
553	        // Check assertions: were the predicted triples actually added?
554	        let assertions_ok = transition.assertions.iter().all(|(s, p, o)| {
555	            triples
556	                .iter()
557	                .any(|t| t.subject == *s && t.predicate == *p && t.object == *o)
558	        });
559	
560	        // Check retractions: were the predicted triples actually removed?
561	        let retractions_ok = transition.retractions.iter().all(|(s, p, o)| {
562	            !triples
563	                .iter()
564	                .any(|t| t.subject == *s && t.predicate == *p && t.object == *o)
565	        });
566	
567	        assertions_ok && retractions_ok
568	    }
