570	    /// Update a schema's statistics after observing an outcome.
571	    pub fn update_schema_from_outcome(
572	        &mut self,
573	        action_name: &str,
574	        success: bool,
575	    ) {
576	        if let Some(schema) = self.schemas.get_mut(action_name) {
577	            schema.execution_count += 1;
578	            // Exponential moving average for success rate.
579	            let alpha = 1.0 / (1.0 + schema.execution_count as f32 * 0.1);
580	            let outcome = if success { 1.0 } else { 0.0 };
581	            schema.success_rate = schema.success_rate * (1.0 - alpha) + outcome * alpha;
582	        }
583	    }
