585	    // ─── Causal Strength ───────────────────────────────────────────
586	
587	    /// Compute the causal strength between cause and effect entities.
588	    ///
589	    /// Looks for direct causal links and transitive chains (depth 2).
590	    pub fn causal_strength(
591	        &self,
592	        cause: SymbolId,
593	        effect: SymbolId,
594	        engine: &Engine,
595	    ) -> f32 {
596	        let preds = match &self.predicates {
597	            Some(p) => p,
598	            None => return 0.0,
599	        };
600	
601	        // Direct link?
602	        let triples = engine.triples_from(cause);
603	        for t in &triples {
604	            if t.object == effect && t.predicate == preds.causes {
605	                return t.confidence;
606	            }
607	        }
608	
609	        // Transitive (depth 2): cause → intermediate → effect
610	        let mut best = 0.0_f32;
611	        for t1 in &triples {
612	            if t1.predicate == preds.causes || t1.predicate == preds.enables {
613	                let intermediate_triples = engine.triples_from(t1.object);
614	                for t2 in &intermediate_triples {
615	                    if t2.object == effect && t2.predicate == preds.causes {
616	                        let transitive =
617	                            t1.confidence * t2.confidence * 0.8;
618	                        best = best.max(transitive);
619	                    }
620	                }
621	            }
622	        }
623	        best
624	    }
