626	    // ─── VSA Encoding ──────────────────────────────────────────────
627	
628	    /// Encode a state-action pair as a HyperVec for similarity lookup.
629	    pub fn encode_state_action(
630	        &self,
631	        ops: &VsaOps,
632	        state_triples: &[Triple],
633	        action_id: SymbolId,
634	    ) -> Option<HyperVec> {
635	        let roles = self.role_vectors.as_ref()?;
636	
637	        // Encode state: bundle up to 20 most-recent triples.
638	        let state_vecs: Vec<HyperVec> = state_triples
639	            .iter()
640	            .rev()
641	            .take(20)
642	            .filter_map(|t| {
643	                let s = crate::vsa::encode::encode_symbol(ops, t.subject);
644	                let p = crate::vsa::encode::encode_symbol(ops, t.predicate);
645	                ops.bind(&s, &p).ok()
646	            })
647	            .collect();
648	
649	        if state_vecs.is_empty() {
650	            return None;
651	        }
652	        let state_refs: Vec<&HyperVec> = state_vecs.iter().collect();
653	        let state_bundle = ops.bundle(&state_refs).ok()?;
654	
655	        // Encode action.
656	        let action_vec = crate::vsa::encode::encode_symbol(ops, action_id);
657	
658	        // Bind state with state-role and action with action-role, then bundle.
659	        let state_bound = ops.bind(&roles.state, &state_bundle).ok()?;
660	        let action_bound = ops.bind(&roles.action, &action_vec).ok()?;
661	
662	        ops.bundle(&[&state_bound, &action_bound]).ok()
663	    }
