666	
667	    /// Record provenance for a learned causal schema.
668	    pub fn record_schema_provenance(
669	        &self,
670	        engine: &Engine,
671	        action_name: &str,
672	        precondition_count: usize,
673	        effect_count: usize,
674	    ) -> CausalResult<()> {
675	        let schema = self
676	            .schemas
677	            .get(action_name)
678	            .ok_or_else(|| CausalError::SchemaNotFound {
679	                name: action_name.into(),
680	            })?;
681	
682	        let mut record = crate::provenance::ProvenanceRecord::new(
683	            schema.action_id,
684	            DerivationKind::CausalSchemaLearned {
685	                action_name: action_name.to_string(),
686	                precondition_count: precondition_count as u32,
687	                effect_count: effect_count as u32,
688	            },
689	        )
690	        .with_confidence(schema.success_rate);
691	        engine
692	            .store_provenance(&mut record)
693	            .map_err(|e| CausalError::Engine(Box::new(e)))?;
694	        Ok(())
695	    }
696	}
