193	impl TaskTree {
194	    /// Produce nodes in topological order via Kahn's algorithm (petgraph).
195	    ///
196	    /// Returns `Err` if the DAG contains a cycle.
197	    pub fn topological_order(&self) -> DecompositionResult<Vec<NodeIndex>> {
198	        petgraph::algo::toposort(&self.dag, None).map_err(|_| DecompositionError::CycleDetected {
199	            method_name: self.method_name.clone(),
200	        })
201	    }
202	
203	    /// Compute the critical path — longest path through the DAG by `estimated_cycles`.
204	    ///
205	    /// Returns the total estimated cycles of the critical path, and the path's node indices.
206	    pub fn critical_path(&self) -> DecompositionResult<(u32, Vec<NodeIndex>)> {
207	        let topo = self.topological_order()?;
208	        if topo.is_empty() {
209	            return Ok((0, Vec::new()));
210	        }
211	
212	        // Dynamic programming: longest path from each node.
213	        let mut dist: std::collections::HashMap<NodeIndex, u32> = std::collections::HashMap::new();
214	        let mut pred: std::collections::HashMap<NodeIndex, Option<NodeIndex>> =
215	            std::collections::HashMap::new();
216	
217	        for &node in &topo {
218	            let node_cost = self.dag[node].estimated_cycles;
219	            dist.insert(node, node_cost);
220	            pred.insert(node, None);
221	        }
222	
223	        for &node in &topo {
224	            let current_dist = dist[&node];
225	            for neighbor in self.dag.neighbors(node) {
226	                let neighbor_cost = self.dag[neighbor].estimated_cycles;
227	                let new_dist = current_dist + neighbor_cost;
228	                if new_dist > dist[&neighbor] {
229	                    dist.insert(neighbor, new_dist);
230	                    pred.insert(neighbor, Some(node));
231	                }
232	            }
233	        }
234	
235	        // Find the node with the maximum distance.
236	        let (&end_node, &max_dist) = dist.iter().max_by_key(|&(_, &d)| d).unwrap();
237	
238	        // Reconstruct path.
239	        let mut path = vec![end_node];
240	        let mut current = end_node;
241	        while let Some(Some(prev)) = pred.get(&current) {
242	            path.push(*prev);
243	            current = *prev;
244	        }
245	        path.reverse();
246	
247	        Ok((max_dist, path))
248	    }
249	
250	    /// Extract sub-goal nodes in topological order.
251	    pub fn to_sub_goals(&self) -> DecompositionResult<Vec<(String, u8, String)>> {
252	        let topo = self.topological_order()?;
253	        let mut sub_goals = Vec::new();
254	
255	        for idx in topo {
256	            if let TaskNodeKind::SubGoal {
257	                ref description,
258	                priority,
259	                ref success_criteria,
260	            } = self.dag[idx].kind
261	            {
262	                sub_goals.push((description.clone(), priority, success_criteria.clone()));
263	            }
264	        }
265	
266	        Ok(sub_goals)
267	    }
268	}
