295	impl MethodRegistry {
296	    /// Create an empty registry.
297	    pub fn new() -> Self {
298	        Self {
299	            methods: Vec::new(),
300	        }
301	    }
302	
303	    /// Register a decomposition method.
304	    pub fn register(&mut self, method: DecompositionMethod) {
305	        self.methods.push(method);
306	    }
307	
308	    /// How many methods are registered.
309	    pub fn len(&self) -> usize {
310	        self.methods.len()
311	    }
312	
313	    /// Whether the registry is empty.
314	    pub fn is_empty(&self) -> bool {
315	        self.methods.is_empty()
316	    }
317	
318	    /// Select the best method for a goal using hybrid keyword + VSA scoring.
319	    ///
320	    /// Returns `None` if no method scores above the 0.2 threshold.
321	    pub fn select_method(&self, goal: &Goal, engine: &Engine) -> Option<&DecompositionMethod> {
322	        if self.methods.is_empty() {
323	            return None;
324	        }
325	
326	        let goal_lower = goal.description.to_lowercase();
327	        let goal_words: Vec<&str> = goal_lower.split_whitespace().collect();
328	
329	        // Encode goal as a VSA vector for semantic matching.
330	        let ops = engine.ops();
331	        let im = engine.item_memory();
332	        let goal_vec = crate::vsa::grounding::encode_text_as_vector(
333	            &goal.description,
334	            engine,
335	            ops,
336	            im,
337	        )
338	        .ok();
339	
340	        let mut best_score = 0.0f32;
341	        let mut best_method: Option<&DecompositionMethod> = None;
342	
343	        for method in &self.methods {
344	            // 1. Keyword score: fraction of method keywords found in goal.
345	            let keyword_score = if method.keyword_hints.is_empty() {
346	                0.0
347	            } else {
348	                let matched = method
349	                    .keyword_hints
350	                    .iter()
351	                    .filter(|kw| goal_words.iter().any(|w| w.contains(kw.as_str())))
352	                    .count();
353	                matched as f32 / method.keyword_hints.len() as f32
354	            };
355	
356	            // 2. Semantic score: VSA similarity between goal and method vectors.
357	            let semantic_score = match (&goal_vec, &method.semantic_vector) {
358	                (Some(gv), Some(mv)) => ops.similarity(gv, mv).unwrap_or(0.5),
359	                _ => {
360	                    // Fallback: encode method keywords as vector on the fly.
361	                    goal_vec
362	                        .as_ref()
363	                        .and_then(|gv| {
364	                            let keywords: Vec<&str> =
365	                                method.keyword_hints.iter().map(|s| s.as_str()).collect();
366	                            crate::vsa::grounding::bundle_symbols(engine, ops, im, &keywords)
367	                                .ok()
368	                                .and_then(|mv| ops.similarity(gv, &mv).ok())
369	                        })
370	                        .unwrap_or(0.5)
371	                }
372	            };
373	
374	            // 3. Success bonus from historical success rate.
375	            let success_bonus = method.success_rate * 0.1;
376	
377	            // 4. Complexity penalty: prefer simpler decompositions.
378	            let complexity_penalty = method.subtask_templates.len() as f32 * 0.05;
379	
380	            // 5. Total score.
381	            let total =
382	                keyword_score * 0.4 + semantic_score * 0.4 + success_bonus - complexity_penalty;
383	
384	            if total > best_score {
385	                best_score = total;
386	                best_method = Some(method);
387	            }
388	        }
389	
390	        // Only return a method if it scores above the threshold.
391	        if best_score >= 0.2 {
392	            best_method
393	        } else {
394	            None
395	        }
396	    }
397	
398	    /// Get the methods (for serialization / stats).
399	    pub fn methods(&self) -> &[DecompositionMethod] {
400	        &self.methods
401	    }
402	
403	    /// Get mutable methods (for updating stats).
404	    pub fn methods_mut(&mut self) -> &mut [DecompositionMethod] {
405	        &mut self.methods
406	    }
407	
408	    /// Remove all methods registered by a specific skill.
409	    ///
410	    /// Skill methods use the naming convention `"skill/{skill_id}/{goal_name}"`.
411	    /// Returns the number of methods removed.
412	    pub fn remove_methods_by_skill(&mut self, skill_id: &str) -> usize {
413	        let prefix = format!("skill/{skill_id}/");
414	        let before = self.methods.len();
415	        self.methods.retain(|m| !m.name.starts_with(&prefix));
416	        before - self.methods.len()
417	    }
418	}
