686	
687	// ---------------------------------------------------------------------------
688	// Decomposition algorithm
689	// ---------------------------------------------------------------------------
690	
691	/// Instantiate a method's templates for a specific goal, building a TaskTree DAG.
692	pub fn decompose_with_method(
693	    goal: &Goal,
694	    method: &DecompositionMethod,
695	) -> DecompositionResult<TaskTree> {
696	    let goal_short = goal
697	        .description
698	        .chars()
699	        .take(40)
700	        .collect::<String>();
701	
702	    let mut dag: DiGraph<TaskNode, DependencyEdge> = DiGraph::new();
703	    let mut node_indices: Vec<NodeIndex> = Vec::new();
704	
705	    // Create a node for each subtask template.
706	    for (i, template) in method.subtask_templates.iter().enumerate() {
707	        let description = template
708	            .description_template
709	            .replace("{goal}", &goal_short);
710	        let criteria = template.criteria_template.replace("{goal}", &goal_short);
711	
712	        let priority = (goal.priority as i16 + template.priority_offset as i16)
713	            .clamp(0, 255) as u8;
714	
715	        let node = TaskNode {
716	            kind: TaskNodeKind::SubGoal {
717	                description,
718	                priority,
719	                success_criteria: criteria,
720	            },
721	            estimated_cycles: 3, // Default estimate.
722	            rationale: format!("Step {} of {} method", i + 1, method.name),
723	        };
724	
725	        node_indices.push(dag.add_node(node));
726	    }
727	
728	    // Add ordering edges.
729	    for &(earlier, later) in &method.ordering {
730	        if earlier < node_indices.len() && later < node_indices.len() {
731	            dag.add_edge(
732	                node_indices[earlier],
733	                node_indices[later],
734	                DependencyEdge::FinishToStart,
735	            );
736	        }
737	    }
738	
739	    // Validate: no cycles.
740	    if petgraph::algo::toposort(&dag, None).is_err() {
741	        return Err(DecompositionError::CycleDetected {
742	            method_name: method.name.clone(),
743	        });
744	    }
745	
746	    // Identify roots (no incoming edges).
747	    let roots: Vec<NodeIndex> = node_indices
748	        .iter()
749	        .copied()
750	        .filter(|&idx| {
751	            dag.neighbors_directed(idx, petgraph::Direction::Incoming)
752	                .next()
753	                .is_none()
754	        })
755	        .collect();
756	
757	    Ok(TaskTree {
758	        dag,
759	        strategy: method.strategy.clone(),
760	        method_name: method.name.clone(),
761	        roots,
762	    })
763	}
764	
765	/// Orchestrator: select a method, decompose, return full result.
766	///
767	/// Falls back to `generate_sub_goal_descriptions()` if no HTN method matches.
768	pub fn decompose_goal_htn(
769	    goal: &Goal,
770	    engine: &Engine,
771	    registry: &MethodRegistry,
772	) -> DecompositionOutput {
773	    // Try HTN method selection.
774	    if let Some(method) = registry.select_method(goal, engine) {
775	        match decompose_with_method(goal, method) {
776	            Ok(tree) => {
777	                // Extract sub-goals and dependencies.
778	                let sub_goals = tree.to_sub_goals().unwrap_or_default();
779	
780	                // Build dependency map: for each sub-goal pair that has an edge,
781	                // record (blocker_idx, blocked_idx) based on sub_goals vec indices.
782	                let topo = tree.topological_order().unwrap_or_default();
783	                let dependencies = extract_dependencies(&tree, &topo);
784	
785	                let rationale = format!(
786	                    "HTN decomposition via '{}' method (strategy: {}), {} sub-goals, {} dependencies",
787	                    method.name,
788	                    method.strategy,
789	                    sub_goals.len(),
790	                    dependencies.len(),
791	                );
792	
793	                return DecompositionOutput {
794	                    tree,
795	                    sub_goals,
796	                    dependencies,
797	                    rationale,
798	                };
799	            }
800	            Err(DecompositionError::CycleDetected { .. }) => {
801	                // Fall through to comma-split fallback.
802	            }
803	            Err(_) => {
804	                // Fall through to comma-split fallback.
805	            }
806	        }
807	    }
808	
809	    // Fallback: existing comma/and splitting.
810	    let sub_descs = goal::generate_sub_goal_descriptions(&goal.description);
811	    let sub_goals: Vec<(String, u8, String)> = sub_descs;
812	
813	    // Build a trivial sequential TaskTree for the fallback.
814	    let mut dag: DiGraph<TaskNode, DependencyEdge> = DiGraph::new();
815	    let mut node_indices: Vec<NodeIndex> = Vec::new();
816	
817	    for (desc, priority, criteria) in &sub_goals {
818	        let node = TaskNode {
819	            kind: TaskNodeKind::SubGoal {
820	                description: desc.clone(),
821	                priority: *priority,
822	                success_criteria: criteria.clone(),
823	            },
824	            estimated_cycles: 3,
825	            rationale: "Comma-split fallback".into(),
826	        };
827	        node_indices.push(dag.add_node(node));
828	    }
829	
830	    // Sequential ordering for fallback.
831	    for i in 0..node_indices.len().saturating_sub(1) {
832	        dag.add_edge(
833	            node_indices[i],
834	            node_indices[i + 1],
835	            DependencyEdge::FinishToStart,
836	        );
837	    }
838	
839	    let roots = node_indices.first().copied().into_iter().collect();
840	
841	    let tree = TaskTree {
842	        dag,
843	        strategy: DecompositionStrategy::Custom("comma-split".into()),
844	        method_name: "fallback".into(),
845	        roots,
846	    };
847	
848	    DecompositionOutput {
849	        tree,
850	        sub_goals,
851	        dependencies: Vec::new(),
852	        rationale: "Fallback: comma/and splitting (no HTN method matched)".into(),
853	    }
854	}
855	
856	/// Extract dependency pairs from a TaskTree as (blocker_idx, blocked_idx)
857	/// into the sub-goal ordering.
858	fn extract_dependencies(tree: &TaskTree, topo: &[NodeIndex]) -> Vec<(usize, usize)> {
859	    use petgraph::visit::EdgeRef;
860	
861	    // Build index: NodeIndex → position in topo order.
862	    let pos: std::collections::HashMap<NodeIndex, usize> = topo
863	        .iter()
864	        .enumerate()
865	        .map(|(i, &idx)| (idx, i))
866	        .collect();
867	
868	    let mut deps = Vec::new();
869	    for edge in tree.dag.edge_references() {
870	        if let (Some(&from_pos), Some(&to_pos)) = (pos.get(&edge.source()), pos.get(&edge.target()))
871	        {
872	            deps.push((from_pos, to_pos));
873	        }
874	    }
875	
876	    deps
877	}
878	
879	// ---------------------------------------------------------------------------
880	// Method stats serialization (for session persistence)
881	// ---------------------------------------------------------------------------
882	
883	/// Serializable snapshot of method usage stats.
884	#[derive(Debug, Serialize, Deserialize)]
885	pub struct MethodStats {
886	    pub name: String,
887	    pub usage_count: u32,
888	    pub success_rate: f32,
889	}
890	
891	impl MethodRegistry {
892	    /// Export stats for persistence.
893	    pub fn export_stats(&self) -> Vec<MethodStats> {
894	        self.methods
895	            .iter()
896	            .map(|m| MethodStats {
897	                name: m.name.clone(),
898	                usage_count: m.usage_count,
899	                success_rate: m.success_rate,
900	            })
901	            .collect()
902	    }
903	
904	    /// Import stats from a persisted snapshot.
905	    pub fn import_stats(&mut self, stats: &[MethodStats]) {
906	        for stat in stats {
907	            if let Some(method) = self.methods.iter_mut().find(|m| m.name == stat.name) {
908	                method.usage_count = stat.usage_count;
909	                method.success_rate = stat.success_rate;
910	            }
911	        }
912	    }
913	}
914	
915	// ---------------------------------------------------------------------------
916	// Plan::from_task_tree
917	// ---------------------------------------------------------------------------
918	
919	impl super::plan::Plan {
920	    /// Flatten a TaskTree into a linear Plan by extracting PlanStep nodes
921	    /// in topological order. SubGoal nodes are skipped (they become separate goals).
922	    pub fn from_task_tree(tree: &TaskTree, goal_id: SymbolId) -> Option<super::plan::Plan> {
923	        let topo = tree.topological_order().ok()?;
924	        let mut steps = Vec::new();
925	
926	        for idx in &topo {
927	            if let TaskNodeKind::PlanStep(ref step) = tree.dag[*idx].kind {
928	                let mut s = step.clone();
929	                s.index = steps.len();
930	                steps.push(s);
931	            }
932	        }
933	
934	        if steps.is_empty() {
935	            return None;
936	        }
937	
938	        Some(super::plan::Plan {
939	            goal_id,
940	            steps,
941	            status: super::plan::PlanStatus::Active,
942	            attempt: 0,
943	            strategy: format!("HTN {} ({})", tree.method_name, tree.strategy),
944	        })
945	    }
946	}
