1	//! Skill manager: discover, warm, activate, and deactivate skillpacks.
2	//!
3	//! Scans a skills directory for subdirectories containing `skill.json` manifests.
4	//! Each skill follows the lifecycle: Cold → Warm → Hot.
5	
6	use std::collections::HashMap;
7	use std::path::PathBuf;
8	use std::sync::atomic::{AtomicUsize, Ordering};
9	use std::sync::RwLock;
10	
11	use egg::{Pattern, Rewrite};
12	
13	use crate::error::{SkillError, SkillResult};
14	use crate::graph::index::KnowledgeGraph;
15	use crate::graph::Triple;
16	use crate::reason::AkhLang;
17	use crate::symbol::SymbolId;
18	
19	use super::{
20	    LoadedSkill, SkillAction, SkillActivation, SkillInfo, SkillManifest, SkillPlan, SkillState,
21	};
22	
23	/// Manages the lifecycle of skillpacks.
24	pub struct SkillManager {
25	    skills_dir: PathBuf,
26	    skills: RwLock<HashMap<String, LoadedSkill>>,
27	    loaded_bytes: AtomicUsize,
28	    max_bytes: usize,
29	    /// Stored rule text per skill: skill_id -> Vec<(name, lhs, rhs)>.
30	    #[allow(clippy::type_complexity)]
31	    rule_sources: RwLock<HashMap<String, Vec<(String, String, String)>>>,
32	}
33	
34	impl std::fmt::Debug for SkillManager {
35	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
36	        f.debug_struct("SkillManager")
37	            .field("skills_dir", &self.skills_dir)
38	            .field("loaded_bytes", &self.loaded_bytes.load(Ordering::Relaxed))
39	            .field("max_bytes", &self.max_bytes)
40	            .finish()
41	    }
42	}
43	
44	impl SkillManager {
45	    /// Create a new skill manager.
46	    ///
47	    /// `max_memory_mb` is the total memory budget for loaded skillpacks.
48	    pub fn new(skills_dir: PathBuf, max_memory_mb: usize) -> Self {
49	        Self {
50	            skills_dir,
51	            skills: RwLock::new(HashMap::new()),
52	            loaded_bytes: AtomicUsize::new(0),
53	            max_bytes: max_memory_mb * 1024 * 1024,
54	            rule_sources: RwLock::new(HashMap::new()),
55	        }
56	    }
57	
58	    /// Get the skills directory path.
59	    pub fn skills_dir(&self) -> &std::path::Path {
60	        &self.skills_dir
61	    }
62	
63	    /// Scan the skills directory for subdirectories containing `skill.json`.
64	    ///
65	    /// Registers each found skill as Cold. Returns the number of skills discovered.
66	    pub fn discover(&self) -> SkillResult<usize> {
67	        if !self.skills_dir.exists() {
68	            return Err(SkillError::NoSkillsDir {
69	                path: self.skills_dir.display().to_string(),
70	            });
71	        }
72	
73	        let entries = std::fs::read_dir(&self.skills_dir).map_err(|e| SkillError::Io {
74	            skill_id: "<discovery>".into(),
75	            source: e,
76	        })?;
77	
78	        let mut count = 0;
79	        let mut skills = self.skills.write().expect("skills lock poisoned");
80	
81	        for entry in entries {
82	            let entry = entry.map_err(|e| SkillError::Io {
83	                skill_id: "<discovery>".into(),
84	                source: e,
85	            })?;
86	            let path = entry.path();
87	            if !path.is_dir() {
88	                continue;
89	            }
90	
91	            let manifest_path = path.join("skill.json");
92	            if !manifest_path.exists() {
93	                continue;
94	            }
95	
96	            // Use the directory name as the skill ID for discovery.
97	            let skill_id = path
98	                .file_name()
99	                .and_then(|n| n.to_str())
100	                .unwrap_or("unknown")
101	                .to_string();
102	
103	            if !skills.contains_key(&skill_id) {
104	                skills.insert(
105	                    skill_id.clone(),
106	                    LoadedSkill {
107	                        manifest: SkillManifest {
108	                            id: skill_id,
109	                            name: String::new(),
110	                            version: String::new(),
111	                            description: String::new(),
112	                            domains: Vec::new(),
113	                            weight_size_bytes: 0,
114	                            triples_file: None,
115	                            rules_file: None,
116	                            cli_tools: Vec::new(),
117	                            wasm_tools: Vec::new(),
118	                            tool_config: std::collections::HashMap::new(),
119	                            actions_file: None,
120	                            plans_file: None,
121	                            procedures_file: None,
122	                        },
123	                        state: SkillState::Cold,
124	                        triple_count: 0,
125	                        rule_count: 0,
126	                        memory_bytes: 0,
127	                        actions: Vec::new(),
128	                        plans: Vec::new(),
129	                    },
130	                );
131	                count += 1;
132	            }
133	        }
134	
135	        Ok(count)
136	    }
137	
138	    /// Parse the manifest for a Cold skill, transitioning it to Warm.
139	    pub fn warm(&self, skill_id: &str) -> SkillResult<SkillManifest> {
140	        let mut skills = self.skills.write().expect("skills lock poisoned");
141	        let skill = skills
142	            .get_mut(skill_id)
143	            .ok_or_else(|| SkillError::NotFound {
144	                name: skill_id.into(),
145	            })?;
146	
147	        if skill.state != SkillState::Cold {
148	            return Err(SkillError::InvalidTransition {
149	                skill_id: skill_id.into(),
150	                from: skill.state.to_string(),
151	                to: "Warm".into(),
152	            });
153	        }
154	
155	        let manifest_path = self.skills_dir.join(skill_id).join("skill.json");
156	        let content = std::fs::read_to_string(&manifest_path).map_err(|e| SkillError::Io {
157	            skill_id: skill_id.into(),
158	            source: e,
159	        })?;
160	
161	        let manifest: SkillManifest =
162	            serde_json::from_str(&content).map_err(|e| SkillError::InvalidManifest {
163	                path: manifest_path.display().to_string(),
164	                message: e.to_string(),
165	            })?;
166	
167	        skill.manifest = manifest.clone();
168	        skill.state = SkillState::Warm;
169	
170	        Ok(manifest)
171	    }
172	
173	    /// Activate a Warm skill: load triples into the knowledge graph
174	    /// and parse rules. Transitions the skill to Hot.
175	    pub fn activate(
176	        &self,
177	        skill_id: &str,
178	        knowledge_graph: &KnowledgeGraph,
179	    ) -> SkillResult<SkillActivation> {
180	        let mut skills = self.skills.write().expect("skills lock poisoned");
181	        let skill = skills
182	            .get_mut(skill_id)
183	            .ok_or_else(|| SkillError::NotFound {
184	                name: skill_id.into(),
185	            })?;
186	
187	        if skill.state != SkillState::Warm {
188	            return Err(SkillError::InvalidTransition {
189	                skill_id: skill_id.into(),
190	                from: skill.state.to_string(),
191	                to: "Hot".into(),
192	            });
193	        }
194	
195	        let skill_dir = self.skills_dir.join(skill_id);
196	        let mut triples_loaded = 0usize;
197	        let mut rules_loaded = 0usize;
198	        let mut memory_estimate = 0usize;
199	
200	        // Load triples if available.
201	        let triples_file = skill
202	            .manifest
203	            .triples_file
204	            .clone()
205	            .unwrap_or_else(|| "triples.json".into());
206	        let triples_path = skill_dir.join(&triples_file);
207	        if triples_path.exists() {
208	            let content = std::fs::read_to_string(&triples_path).map_err(|e| SkillError::Io {
209	                skill_id: skill_id.into(),
210	                source: e,
211	            })?;
212	
213	            let raw_triples: Vec<serde_json::Value> =
214	                serde_json::from_str(&content).map_err(|e| SkillError::InvalidManifest {
215	                    path: triples_path.display().to_string(),
216	                    message: format!("triples parse error: {e}"),
217	                })?;
218	
219	            for val in &raw_triples {
220	                let s = val["s"].as_u64().unwrap_or(0);
221	                let p = val["p"].as_u64().unwrap_or(0);
222	                let o = val["o"].as_u64().unwrap_or(0);
223	
224	                if let (Some(s), Some(p), Some(o)) =
225	                    (SymbolId::new(s), SymbolId::new(p), SymbolId::new(o))
226	                {
227	                    // Ignore duplicate triple errors.
228	                    let _ = knowledge_graph.insert_triple(&Triple::new(s, p, o));
229	                    triples_loaded += 1;
230	                }
231	            }
232	
233	            memory_estimate += content.len();
234	        }
235	
236	        // Load rules if available.
237	        let rules_file = skill
238	            .manifest
239	            .rules_file
240	            .clone()
241	            .unwrap_or_else(|| "rules.txt".into());
242	        let rules_path = skill_dir.join(&rules_file);
243	        let mut rule_tuples: Vec<(String, String, String)> = Vec::new();
244	        if rules_path.exists() {
245	            let content = std::fs::read_to_string(&rules_path).map_err(|e| SkillError::Io {
246	                skill_id: skill_id.into(),
247	                source: e,
248	            })?;
249	
250	            for (i, line) in content.lines().enumerate() {
251	                let line = line.trim();
252	                if line.is_empty() || line.starts_with('#') {
253	                    continue;
254	                }
255	                if let Some((lhs, rhs)) = line.split_once("=>") {
256	                    let name = format!("{}-rule-{}", skill_id, i);
257	                    rule_tuples.push((name, lhs.trim().to_string(), rhs.trim().to_string()));
258	                    rules_loaded += 1;
259	                } else {
260	                    return Err(SkillError::InvalidRule {
261	                        skill_id: skill_id.into(),
262	                        message: format!("line {}: missing '=>' separator", i + 1),
263	                    });
264	                }
265	            }
266	
267	            memory_estimate += content.len();
268	        }
269	
270	        // ── Phase 30: Load action schemas (actions.json) ────────────────────
271	        let actions_file = skill
272	            .manifest
273	            .actions_file
274	            .clone()
275	            .unwrap_or_else(|| "actions.json".into());
276	        let actions_path = skill_dir.join(&actions_file);
277	        let mut loaded_actions: Vec<SkillAction> = Vec::new();
278	        if actions_path.exists() {
279	            let content = std::fs::read_to_string(&actions_path).map_err(|e| SkillError::Io {
280	                skill_id: skill_id.into(),
281	                source: e,
282	            })?;
283	            loaded_actions =
284	                serde_json::from_str(&content).map_err(|e| SkillError::InvalidManifest {
285	                    path: actions_path.display().to_string(),
286	                    message: format!("actions parse error: {e}"),
287	                })?;
288	            memory_estimate += content.len();
289	        }
290	
291	        // ── Phase 30: Load plan templates (plans.json) ───────────────────────
292	        let plans_file = skill
293	            .manifest
294	            .plans_file
295	            .clone()
296	            .unwrap_or_else(|| "plans.json".into());
297	        let plans_path = skill_dir.join(&plans_file);
298	        let mut loaded_plans: Vec<SkillPlan> = Vec::new();
299	        if plans_path.exists() {
300	            let content = std::fs::read_to_string(&plans_path).map_err(|e| SkillError::Io {
301	                skill_id: skill_id.into(),
302	                source: e,
303	            })?;
304	            loaded_plans =
305	                serde_json::from_str(&content).map_err(|e| SkillError::InvalidManifest {
306	                    path: plans_path.display().to_string(),
307	                    message: format!("plans parse error: {e}"),
308	                })?;
309	            memory_estimate += content.len();
310	        }
311	
312	        let actions_loaded = loaded_actions.len();
313	        let plans_loaded = loaded_plans.len();
314	
315	        // Check memory budget.
316	        let current = self.loaded_bytes.load(Ordering::Relaxed);
317	        if current + memory_estimate > self.max_bytes {
318	            return Err(SkillError::MemoryBudgetExceeded {
319	                required_mb: memory_estimate / (1024 * 1024) + 1,
320	                available_mb: (self.max_bytes.saturating_sub(current)) / (1024 * 1024),
321	            });
322	        }
323	
324	        // Commit.
325	        self.loaded_bytes
326	            .fetch_add(memory_estimate, Ordering::Relaxed);
327	        skill.state = SkillState::Hot;
328	        skill.triple_count = triples_loaded;
329	        skill.rule_count = rules_loaded;
330	        skill.memory_bytes = memory_estimate;
331	        skill.actions = loaded_actions;
332	        skill.plans = loaded_plans;
333	
334	        if !rule_tuples.is_empty() {
335	            self.rule_sources
336	                .write()
337	                .expect("rule_sources lock poisoned")
338	                .insert(skill_id.to_string(), rule_tuples);
339	        }
340	
341	        if actions_loaded > 0 {
342	            tracing::debug!(skill_id, actions_loaded, "loaded procedural action schemas");
343	        }
344	        if plans_loaded > 0 {
345	            tracing::debug!(skill_id, plans_loaded, "loaded procedural plan templates");
346	        }
347	
348	        Ok(SkillActivation {
349	            skill_id: skill_id.into(),
350	            triples_loaded,
351	            rules_loaded,
352	            memory_bytes: memory_estimate,
353	            actions_loaded,
354	            plans_loaded,
355	        })
356	    }
357	
358	    /// Deactivate a Hot skill: mark inactive, free budget.
359	    /// Triples already in the KG persist until engine restart.
360	    pub fn deactivate(&self, skill_id: &str) -> SkillResult<()> {
361	        let mut skills = self.skills.write().expect("skills lock poisoned");
362	        let skill = skills
363	            .get_mut(skill_id)
364	            .ok_or_else(|| SkillError::NotFound {
365	                name: skill_id.into(),
366	            })?;
367	
368	        if skill.state != SkillState::Hot {
369	            return Err(SkillError::InvalidTransition {
370	                skill_id: skill_id.into(),
371	                from: skill.state.to_string(),
372	                to: "Warm (deactivate)".into(),
373	            });
374	        }
375	
376	        self.loaded_bytes
377	            .fetch_sub(skill.memory_bytes, Ordering::Relaxed);
378	        skill.state = SkillState::Warm;
379	        skill.memory_bytes = 0;
380	        // Clear procedural data (Phase 30).
381	        skill.actions.clear();
382	        skill.plans.clear();
383	
384	        self.rule_sources
385	            .write()
386	            .expect("rule_sources lock poisoned")
387	            .remove(skill_id);
388	
389	        Ok(())
390	    }
391	
392	    /// Get the current state of a skill, or `None` if not discovered.
393	    pub fn skill_state(&self, skill_id: &str) -> Option<SkillState> {
394	        let skills = self.skills.read().expect("skills lock poisoned");
395	        skills.get(skill_id).map(|s| s.state)
396	    }
397	
398	    /// Build an activation summary for an already-Hot skill (idempotent reload).
399	    pub fn hot_activation(&self, skill_id: &str) -> Option<SkillActivation> {
400	        let skills = self.skills.read().expect("skills lock poisoned");
401	        let skill = skills.get(skill_id)?;
402	        if skill.state != SkillState::Hot {
403	            return None;
404	        }
405	        Some(SkillActivation {
406	            skill_id: skill_id.to_string(),
407	            triples_loaded: skill.triple_count,
408	            rules_loaded: skill.rule_count,
409	            memory_bytes: skill.memory_bytes,
410	            actions_loaded: skill.actions.len(),
411	            plans_loaded: skill.plans.len(),
412	        })
413	    }
414	
415	    /// Add extra triples to a Hot skill's count (e.g. label triples loaded externally).
416	    pub fn add_triple_count(&self, skill_id: &str, extra: usize) {
417	        let mut skills = self.skills.write().expect("skills lock poisoned");
418	        if let Some(skill) = skills.get_mut(skill_id) {
419	            skill.triple_count += extra;
420	        }
421	    }
422	
423	    /// List all known skills with their current state.
424	    pub fn list(&self) -> Vec<SkillInfo> {
425	        let skills = self.skills.read().expect("skills lock poisoned");
426	        skills
427	            .values()
428	            .map(|s| SkillInfo {
429	                id: s.manifest.id.clone(),
430	                name: s.manifest.name.clone(),
431	                version: s.manifest.version.clone(),
432	                description: s.manifest.description.clone(),
433	                state: s.state,
434	                domains: s.manifest.domains.clone(),
435	                triple_count: s.triple_count,
436	                rule_count: s.rule_count,
437	                action_count: s.actions.len(),
438	                plan_count: s.plans.len(),
439	            })
440	            .collect()
441	    }
442	
443	    /// Return the action schemas loaded for a Hot skill (Phase 30).
444	    pub fn actions(&self, skill_id: &str) -> Vec<SkillAction> {
445	        let skills = self.skills.read().expect("skills lock poisoned");
446	        skills
447	            .get(skill_id)
448	            .filter(|s| s.state == SkillState::Hot)
449	            .map(|s| s.actions.clone())
450	            .unwrap_or_default()
451	    }
452	
453	    /// Return the plan templates loaded for a Hot skill (Phase 30).
454	    pub fn plans(&self, skill_id: &str) -> Vec<SkillPlan> {
455	        let skills = self.skills.read().expect("skills lock poisoned");
456	        skills
457	            .get(skill_id)
458	            .filter(|s| s.state == SkillState::Hot)
459	            .map(|s| s.plans.clone())
460	            .unwrap_or_default()
461	    }
462	
463	    /// Return all action schemas from all Hot skills (Phase 30).
464	    pub fn all_active_actions(&self) -> Vec<(String, SkillAction)> {
465	        let skills = self.skills.read().expect("skills lock poisoned");
466	        skills
467	            .values()
468	            .filter(|s| s.state == SkillState::Hot)
469	            .flat_map(|s| {
470	                s.actions
471	                    .iter()
472	                    .map(|a| (s.manifest.id.clone(), a.clone()))
473	                    .collect::<Vec<_>>()
474	            })
475	            .collect()
476	    }
477	
478	    /// Return all plan templates from all Hot skills (Phase 30).
479	    pub fn all_active_plans(&self) -> Vec<(String, SkillPlan)> {
480	        let skills = self.skills.read().expect("skills lock poisoned");
481	        skills
482	            .values()
483	            .filter(|s| s.state == SkillState::Hot)
484	            .flat_map(|s| {
485	                s.plans
486	                    .iter()
487	                    .map(|p| (s.manifest.id.clone(), p.clone()))
488	                    .collect::<Vec<_>>()
489	            })
490	            .collect()
491	    }
492	
493	    /// Build rewrite rules from all active (Hot) skills.
494	    pub fn active_rules(&self) -> Vec<Rewrite<AkhLang, ()>> {
495	        let rule_sources = self
496	            .rule_sources
497	            .read()
498	            .expect("rule_sources lock poisoned");
499	        let mut rules = Vec::new();
500	
501	        for (skill_id, tuples) in rule_sources.iter() {
502	            for (name, lhs, rhs) in tuples {
503	                // egg::rewrite! is a macro; we must use the lower-level API.
504	                let lhs_result: Result<Pattern<AkhLang>, _> = lhs.parse();
505	                let rhs_result: Result<Pattern<AkhLang>, _> = rhs.parse();
506	                if let (Ok(lhs_pat), Ok(rhs_pat)) = (lhs_result, rhs_result) {
507	                    match Rewrite::new(name.clone(), lhs_pat, rhs_pat) {
508	                        Ok(rule) => rules.push(rule),
509	                        Err(e) => {
510	                            tracing::warn!(
511	                                skill_id,
512	                                rule = name.as_str(),
513	                                error = %e,
514	                                "failed to compile skill rule, skipping"
515	                            );
516	                        }
517	                    }
518	                } else {
519	                    tracing::warn!(
520	                        skill_id,
521	                        rule = name.as_str(),
522	                        "failed to parse skill rule patterns, skipping"
523	                    );
524	                }
525	            }
526	        }
527	
528	        rules
529	    }
530	
531	    /// Get info for a specific skill.
532	    pub fn get_info(&self, skill_id: &str) -> SkillResult<SkillInfo> {
533	        let skills = self.skills.read().expect("skills lock poisoned");
534	        let skill = skills.get(skill_id).ok_or_else(|| SkillError::NotFound {
535	            name: skill_id.into(),
536	        })?;
537	        Ok(SkillInfo {
538	            id: skill.manifest.id.clone(),
539	            name: skill.manifest.name.clone(),
540	            version: skill.manifest.version.clone(),
541	            description: skill.manifest.description.clone(),
542	            state: skill.state,
543	            domains: skill.manifest.domains.clone(),
544	            triple_count: skill.triple_count,
545	            rule_count: skill.rule_count,
546	            action_count: skill.actions.len(),
547	            plan_count: skill.plans.len(),
548	        })
549	    }
550	}
